-- ============================================================================
-- Viesa Dashboard — alle standaardsjablonen als SQL
-- ----------------------------------------------------------------------------
-- Doet hetzelfde als de knop "Standaard importeren" op /sjablonen, maar dan
-- rechtstreeks in de database. Handig wanneer de app die knop niet uitvoert of
-- de nieuwe code nog niet gedeployd is.
--
-- Inhoud: 124 sjablonen
--   email: 47
--   belscript: 25
--   offerte: 26
--   audit: 26
--
-- Idempotent: bestaande combinaties van type + naam worden overgeslagen, dus je
-- kunt dit bestand veilig meerdere keren draaien.
--
-- LET OP: draai eerst 0040, 0041 en 0042, anders weigert de database het type
-- 'belscript' en de kolom lettertype.
-- ============================================================================

insert into public.sjablonen (type, naam, onderwerp, inhoud_html, lettertype)
select v.type, v.naam, v.onderwerp, v.inhoud_html, v.lettertype
from (values
  ('email', '1 · We hebben je gezien', 'Wat ons opviel aan {{bedrijf}}', '<p>Beste {{voornaam}},</p><p>We kwamen {{bedrijf}} tegen en het viel ons meteen op: jullie hebben een sterk product en een duidelijke propositie. Precies het soort organisatie waar wij graag mee werken.</p><p>Bij Viesa maken we webshops slimmer en mobieler. We combineren technische e-commerce-expertise met slimme automatisering — geen statische website, maar een systeem dat je bedrijfsvoering versterkt en werk uit handen neemt.</p><p>Ik ben benieuwd: staat het optimaliseren van jullie online-omgeving dit jaar op de agenda? Dan denk ik graag vrijblijvend met je mee.</p><p>Met vriendelijke groet,<br>Tom &amp; Joep<br>Viesa Automations<br>www.viesa-automations.nl</p>', 'times'),
  ('email', '2 · Gevonden op Google', 'Via Google bij {{bedrijf}} terechtgekomen', '<p>Beste {{voornaam}},</p><p>We vonden {{bedrijf}} via Google terwijl we naar sterke spelers in jullie branche zochten. Jullie vielen op — en dat maakte ons nieuwsgierig naar hoe jullie online-omgeving nu presteert.</p><p>Wij helpen bedrijven zoals dat van jou om hun webshop om te zetten naar een volwaardige mobiele app, klantcontact te automatiseren met AI-agents, en handmatige taken te laten verdwijnen via workflow-automatisering.</p><p>Zou een korte, vrijblijvende scan van jullie situatie interessant zijn? Dan laten we concreet zien waar de winst zit.</p><p>Met vriendelijke groet,<br>Tom &amp; Joep<br>Viesa Automations<br>www.viesa-automations.nl</p>', 'times'),
  ('email', '3 · Uitnodiging gratis audit', 'Een gratis audit voor {{bedrijf}}?', '<p>Beste {{voornaam}},</p><p>We zijn benieuwd of je openstaat voor een gratis audit van jullie online-omgeving. In die audit brengen we in kaart waar {{bedrijf}} snelheid, omzet en efficiëntie laat liggen — en hoe je dat terugwint.</p><p>Je ontvangt van ons een helder auditverslag met:<br>• concrete bevindingen over je webshop en processen;<br>• kansen voor een mobiele app, AI-klantcontact en automatisering;<br>• een prioriteitenlijst met verwachte impact.</p><p>Vrijblijvend, en je houdt het verslag sowieso. Zullen we een moment inplannen?</p><p>Met vriendelijke groet,<br>Tom &amp; Joep<br>Viesa Automations<br>www.viesa-automations.nl</p>', 'times'),
  ('email', '4 · We kunnen veel betekenen', 'Waar wij het verschil maken voor {{bedrijf}}', '<p>Beste {{voornaam}},</p><p>We denken dat we veel voor {{bedrijf}} kunnen betekenen. Niet met een nieuwe website, maar met een platform dat staat als een huis en zichzelf continu optimaliseert.</p><p>Wat dat concreet oplevert:<br>• App-ontwikkeling: je webshop als volwaardige mobiele app, optimaal op elk apparaat.<br>• Slimme AI-agents: chatbots en Voice AI die klanten 24/7 professioneel te woord staan.<br>• Workflow-automatisering: systemen die met elkaar praten, zodat handmatig werk verdwijnt en je data altijd klopt.<br>• Intelligente kennisbank: jouw bedrijfs- en productkennis als bron voor AI die antwoorden geeft die écht bij je passen.</p><p>Via onze partnership met Commerced combineren we onze techniek met diepgaande e-commerce-architectuurkennis.</p><p>Zullen we 20 minuten bellen om te kijken wat de grootste kans voor jullie is?</p><p>Met vriendelijke groet,<br>Tom &amp; Joep<br>Viesa Automations<br>www.viesa-automations.nl</p>', 'times'),
  ('email', '5 · Wie zijn wij (introductie)', 'Even voorstellen — Viesa Automations', '<p>Beste {{voornaam}},</p><p>Even kort wie wij zijn. Viesa Automations maakt webshops slimmer en mobieler. We bouwen geen statische websites, maar systemen die je bedrijfsvoering versterken en werk uit handen nemen.</p><p>Onze aanpak in het kort:<br>• We zetten je webshop om naar een volwaardige mobiele app.<br>• We bouwen AI-agents (chat en voice) voor 24/7 klantcontact.<br>• We automatiseren workflows, zodat processen vanzelf lopen.<br>• We ontsluiten je kennis in een intelligente kennisbank.</p><p>Samen met onze partner Commerced leveren we een schaalbaar platform dat zichzelf blijft optimaliseren.</p><p>Ik vertel je er graag meer over — past een korte kennismaking deze of volgende week?</p><p>Met vriendelijke groet,<br>Tom &amp; Joep<br>Viesa Automations<br>www.viesa-automations.nl</p>', 'times'),
  ('email', '6 · Follow-up (1e herinnering)', 'Even terugkomen op mijn bericht', '<p>Beste {{voornaam}},</p><p>Ik kom nog even terug op mijn vorige bericht. Ik snap dat het druk is — daarom houd ik het kort.</p><p>Zou een vrijblijvende audit van jullie online-omgeving interessant zijn? Je krijgt een concreet beeld van de kansen voor {{bedrijf}}, zonder verplichtingen.</p><p>Laat gerust weten of het je aanspreekt, dan plan ik een moment in.</p><p>Met vriendelijke groet,<br>Tom &amp; Joep<br>Viesa Automations<br>www.viesa-automations.nl</p>', 'times'),
  ('email', '7 · Follow-up (laatste)', 'Laatste keer dat ik je hierover mail', '<p>Beste {{voornaam}},</p><p>Ik wil je niet blijven mailen, dus dit is mijn laatste bericht hierover. Mocht optimalisatie van jullie webshop, klantcontact of processen op een later moment spelen, dan hoor ik het graag — de deur staat open.</p><p>Succes met alles bij {{bedrijf}}, en wie weet tot later.</p><p>Met vriendelijke groet,<br>Tom &amp; Joep<br>Viesa Automations<br>www.viesa-automations.nl</p>', 'times'),
  ('email', '8 · Afspraak bevestigen', 'Bevestiging van onze afspraak', '<p>Beste {{voornaam}},</p><p>Fijn dat we een moment hebben ingepland. Hierbij bevestig ik onze afspraak op [datum] om [tijd].</p><p>Ik zorg dat we goed voorbereid zijn en kom met een paar concrete ideeën voor {{bedrijf}}. Mocht het onverhoopt niet uitkomen, laat het tijdig weten, dan plannen we opnieuw.</p><p>Tot dan!</p><p>Met vriendelijke groet,<br>Tom &amp; Joep<br>Viesa Automations<br>www.viesa-automations.nl</p>', 'times'),
  ('email', '9 · Auditverslag nasturen', 'Jullie auditverslag van Viesa Automations', '<p>Beste {{voornaam}},</p><p>Bedankt voor je tijd. Zoals beloofd stuur ik je hierbij het auditverslag van {{bedrijf}}.</p><p>In het verslag vind je onze bevindingen, de belangrijkste kansen en een prioriteitenlijst met verwachte impact. De grootste winst zit wat ons betreft in [kans].</p><p>Ik loop het graag met je door en licht toe hoe we dit stap voor stap kunnen aanpakken. Wanneer schikt het?</p><p>Met vriendelijke groet,<br>Tom &amp; Joep<br>Viesa Automations<br>www.viesa-automations.nl</p>', 'times'),
  ('email', '10 · Offerte nasturen', 'Jullie offerte van Viesa Automations', '<p>Beste {{voornaam}},</p><p>Bedankt voor het prettige gesprek. Zoals besproken stuur ik je hierbij onze offerte voor {{bedrijf}}.</p><p>De offerte is opgebouwd rond de kansen die we samen bespraken, met een heldere fasering en verwachte resultaten. Heb je vragen of wil je iets aanpassen? Laat het gerust weten, dan denk ik graag mee.</p><p>Ik hoor graag wat je ervan vindt.</p><p>Met vriendelijke groet,<br>Tom &amp; Joep<br>Viesa Automations<br>www.viesa-automations.nl</p>', 'times'),
  ('email', '11 · Reactie op aanvraag', 'Bedankt voor je aanvraag bij Viesa', '<p>Beste {{voornaam}},</p><p>Bedankt voor je bericht en je interesse in Viesa Automations. Leuk dat je contact opneemt!</p><p>Om je zo goed mogelijk te helpen: zou je kort kunnen toelichten wat je precies zoekt en wat op dit moment het grootste knelpunt is? Dan kom ik snel bij je terug met een concreet voorstel.</p><p>Met vriendelijke groet,<br>Tom &amp; Joep<br>Viesa Automations<br>www.viesa-automations.nl</p>', 'times'),
  ('email', '12 · Factuurherinnering', 'Vriendelijke herinnering — openstaande factuur', '<p>Beste {{voornaam}},</p><p>Uit onze administratie blijkt dat de factuur met nummer [nummer] nog openstaat. Mogelijk is dit aan je aandacht ontsnapt.</p><p>Wil je de betaling alsnog in orde maken? Is de factuur al voldaan, dan kun je dit bericht als niet verzonden beschouwen.</p><p>Met vriendelijke groet,<br>Tom &amp; Joep<br>Viesa Automations<br>www.viesa-automations.nl</p>', 'times'),
  ('email', '13 · We hebben je gezien (kort)', 'Kort vraagje over {{bedrijf}}', '<p>Beste {{voornaam}},</p><p>{{bedrijf}} viel ons op. Eén concrete vraag: staat het slimmer en mobieler maken van jullie webshop dit jaar op de planning?</p><p>Zo ja, dan laat ik je in 15 minuten zien waar de grootste winst zit. Zo nee, dan hoor je verder niets van me.</p><p>Met vriendelijke groet,<br>Tom &amp; Joep<br>Viesa Automations<br>www.viesa-automations.nl</p>', 'times'),
  ('email', '14 · Gevonden op Google (branche)', 'Opgevallen in jullie branche', '<p>Beste {{voornaam}},</p><p>Bij het verkennen van sterke spelers in jullie branche kwamen we {{bedrijf}} tegen. We zien in deze markt keer op keer dezelfde kans: klanten verwachten een razendsnelle, mobiele ervaring en direct antwoord — 24/7.</p><p>Precies daar zijn wij goed in: een mobiele app van je webshop, AI-agents voor klantcontact en automatisering die handwerk wegneemt.</p><p>Zal ik een korte scan doen en de 3 grootste kansen voor {{bedrijf}} delen?</p><p>Met vriendelijke groet,<br>Tom &amp; Joep<br>Viesa Automations<br>www.viesa-automations.nl</p>', 'times'),
  ('email', '15 · Focus: mobiele app', 'Van webshop naar app voor {{bedrijf}}', '<p>Beste {{voornaam}},</p><p>Steeds meer omzet komt via mobiel. Toch draaien veel webshops nog op een site die op een telefoon ''meekan'' in plaats van te schitteren.</p><p>Wij zetten jouw bestaande webshop om naar een volwaardige mobiele app: sneller, met pushberichten en een ervaring die klanten laat terugkomen. Alles gekoppeld aan je huidige systemen.</p><p>Benieuwd hoe dat er voor {{bedrijf}} uit zou zien? Ik maak graag een korte schets.</p><p>Met vriendelijke groet,<br>Tom &amp; Joep<br>Viesa Automations<br>www.viesa-automations.nl</p>', 'times'),
  ('email', '16 · Focus: AI-agents (chat & voice)', '24/7 klantcontact voor {{bedrijf}}, zonder extra personeel', '<p>Beste {{voornaam}},</p><p>Stel: elke klantvraag bij {{bedrijf}} wordt direct, professioneel en in jullie tone-of-voice beantwoord — dag en nacht, zonder wachttijd.</p><p>Dat bouwen wij met slimme AI-agents: chatbots en Voice AI die je klanten te woord staan, gevoed door jullie eigen kennisbank. Zo krijgen klanten antwoorden die écht kloppen, en houdt je team tijd over voor het echte werk.</p><p>Zal ik laten zien hoe zo''n agent voor jullie zou werken?</p><p>Met vriendelijke groet,<br>Tom &amp; Joep<br>Viesa Automations<br>www.viesa-automations.nl</p>', 'times'),
  ('email', '17 · Focus: workflow-automatisering', 'Handmatig werk wegnemen bij {{bedrijf}}', '<p>Beste {{voornaam}},</p><p>Veel bedrijven verliezen uren aan handmatig overtikken, kopiëren en controleren tussen systemen. Herkenbaar?</p><p>Wij koppelen jullie systemen aan elkaar, zodat handmatige taken verdwijnen, data altijd klopt en processen automatisch lopen. Minder fouten, meer tijd, een organisatie die schaalt.</p><p>Ik breng graag in kaart welke processen bij {{bedrijf}} zich als eerste lenen voor automatisering.</p><p>Met vriendelijke groet,<br>Tom &amp; Joep<br>Viesa Automations<br>www.viesa-automations.nl</p>', 'times'),
  ('email', '18 · Oude lead opnieuw benaderen', 'Nog steeds nieuwsgierig naar {{bedrijf}}', '<p>Beste {{voornaam}},</p><p>Een tijd geleden hadden we contact over het slimmer maken van jullie online-omgeving. De timing was toen misschien niet ideaal — daarom kom ik er nog eens op terug.</p><p>Er is sindsdien veel mogelijk geworden, zeker op het vlak van mobiele apps en AI-klantcontact. Is het interessant om vrijblijvend bij te praten en te kijken wat er nu voor {{bedrijf}} speelt?</p><p>Met vriendelijke groet,<br>Tom &amp; Joep<br>Viesa Automations<br>www.viesa-automations.nl</p>', 'times'),
  ('email', '19 · Bedankt na kennismaking', 'Fijn gesprek — en de vervolgstappen', '<p>Beste {{voornaam}},</p><p>Bedankt voor het prettige gesprek. Kort samengevat wat we bespraken:<br>• Uitdaging: [uitdaging].<br>• Kans: [oplossing/richting].<br>• Vervolg: [vervolgstap].</p><p>Ik pak [actie] op en kom uiterlijk [datum] bij je terug. Mocht er nog iets zijn, laat het gerust weten.</p><p>Met vriendelijke groet,<br>Tom &amp; Joep<br>Viesa Automations<br>www.viesa-automations.nl</p>', 'times'),
  ('email', '20 · Samenwerking & expertise', 'Techniek én e-commerce-kennis voor {{bedrijf}}', '<p>Beste {{voornaam}},</p><p>Wat ons anders maakt: we combineren technische kracht met diepgaande e-commerce-kennis. Via onze partnership met Commerced kijken we niet alleen naar de techniek, maar naar de héle architectuur achter jullie webshop.</p><p>Het resultaat is een schaalbaar platform dat staat als een huis en zichzelf continu optimaliseert — geen los projectje, maar een fundament.</p><p>Ik vertel je graag hoe we dat voor {{bedrijf}} zouden aanpakken.</p><p>Met vriendelijke groet,<br>Tom &amp; Joep<br>Viesa Automations<br>www.viesa-automations.nl</p>', 'times'),
  ('email', '21 · Follow-up na offerte', 'Nog vragen over onze offerte?', '<p>Beste {{voornaam}},</p><p>Ik ben benieuwd of je onze offerte voor {{bedrijf}} al hebt kunnen bekijken. Roept ''ie nog vragen op, of wil je ergens over sparren?</p><p>Ik denk graag mee om ''m precies passend te maken — qua scope, fasering of budget. Laat gerust weten wat voor jullie het beste werkt.</p><p>Met vriendelijke groet,<br>Tom &amp; Joep<br>Viesa Automations<br>www.viesa-automations.nl</p>', 'times'),
  ('email', '22 · Tevredenheid na oplevering', 'Hoe bevalt het tot nu toe?', '<p>Beste {{voornaam}},</p><p>Nu [oplevering/onderdeel] live staat bij {{bedrijf}}, ben ik benieuwd hoe het bevalt. Loopt alles zoals je had gehoopt?</p><p>Mochten er nog puntjes zijn, dan pak ik die graag op. En ben je tevreden? Dan stellen we een korte review enorm op prijs — dat helpt ons om nog meer ondernemers te helpen.</p><p>Met vriendelijke groet,<br>Tom &amp; Joep<br>Viesa Automations<br>www.viesa-automations.nl</p>', 'times'),
  ('email', 'A1 · De ene observatie', 'Iets wat me opviel op {{website}}', '<p>Beste {{voornaam}},</p><p>Ik was op {{website}} en zag [concrete observatie — bv. dat jullie bestellingen per e-mail binnenkomen]. Dat is precies het soort ding waar wij ons dagelijks mee bezighouden.</p><p>Wij bouwen voor webshops en groothandels de koppelingen die dat handwerk wegnemen. Geen nieuw systeem, maar de systemen die je al hebt met elkaar laten praten.</p><p>Speelt dit bij {{bedrijf}}, of zit het al goed?</p><p>Met vriendelijke groet,<br>Tom van Biene<br>Viesa Automations<br>www.viesa-automations.nl</p>', 'times'),
  ('email', 'A2 · Het cijfer', '[X] seconden — en wat dat {{bedrijf}} kost', '<p>Beste {{voornaam}},</p><p>Ik heb {{website}} even door een snelheidstest gehaald. Op mobiel laadt de pagina in [X] seconden.</p><p>Dat klinkt onschuldig, maar de vuistregel is hard: elke seconde erbij kost ongeveer een vijfde van je conversie. Bij jullie volume praat je dan al snel over serieus geld per jaar.</p><p>Ik heb de meting en de drie oorzaken op een rijtje. Zal ik ze sturen?</p><p>Met vriendelijke groet,<br>Tom van Biene<br>Viesa Automations<br>www.viesa-automations.nl</p>', 'times'),
  ('email', 'A3 · De branchegenoot', 'Wat een [branche]-collega vorig kwartaal deed', '<p>Beste {{voornaam}},</p><p>We werken voor een aantal bedrijven in [branche]. Bij vrijwel allemaal kwam hetzelfde naar boven: de webshop draait prima, maar erachter wordt nog veel overgetikt tussen shop, voorraad en boekhouding.</p><p>Bij [type bedrijf] hebben we dat vorig kwartaal dichtgezet. Resultaat: [concreet resultaat, bv. 6 uur per week terug en geen voorraadfouten meer].</p><p>Herkenbaar bij {{bedrijf}}? Dan is het gesprek de moeite waard.</p><p>Met vriendelijke groet,<br>Tom van Biene<br>Viesa Automations<br>www.viesa-automations.nl</p>', 'times'),
  ('email', 'A4 · Eén vraag, tien seconden', 'Eén vraag over {{bedrijf}}', '<p>Beste {{voornaam}},</p><p>Eén vraag, tien seconden werk:</p><p>Staat het automatiseren van jullie orderverwerking dit jaar op de planning?</p><p>Ja → dan stuur ik je iets bruikbaars.<br>Nee → dan hoor je niets meer van me.</p><p>Met vriendelijke groet,<br>Tom van Biene<br>Viesa Automations<br>www.viesa-automations.nl</p>', 'times'),
  ('email', 'A5 · Het signaal', 'Gezien: [signaal] bij {{bedrijf}}', '<p>Beste {{voornaam}},</p><p>Ik zag [signaal — bv. jullie vacature voor een orderverwerker / de overstap naar een nieuw platform / het nieuws over jullie uitbreiding]. Gefeliciteerd — en meteen een gedachte.</p><p>Precies op zo''n moment wordt zichtbaar welk werk eigenlijk niet door een mens gedaan hoeft te worden. Wij bouwen dat soort koppelingen, vaak binnen enkele weken.</p><p>Zou het nuttig zijn om er kort over te sparren voordat jullie het anders inrichten?</p><p>Met vriendelijke groet,<br>Tom van Biene<br>Viesa Automations<br>www.viesa-automations.nl</p>', 'times'),
  ('email', 'A6 · Toestemming vragen', 'Mag ik je iets sturen?', '<p>Beste {{voornaam}},</p><p>Ik ga je niets verkopen in deze mail. Ik wil alleen iets vragen.</p><p>Wij hebben een korte scan waarmee we van buitenaf zien waar bij een webshop tijd en omzet weglekt — laadtijd, mobiele afrekenroute, handmatige stappen in de backoffice. Kost jou niets en duurt bij ons een half uur.</p><p>Mag ik die voor {{bedrijf}} doen en de uitkomst sturen? Eén woord terug is genoeg.</p><p>Met vriendelijke groet,<br>Tom van Biene<br>Viesa Automations<br>www.viesa-automations.nl</p>', 'times'),
  ('email', 'A7 · De omgekeerde pitch', 'Waarschijnlijk niets voor {{bedrijf}}', '<p>Beste {{voornaam}},</p><p>Eerlijk: wij zijn niet voor iedereen. Wat wij doen loont pas als er echt volume doorheen gaat en er nog mensen handmatig zitten over te tikken.</p><p>Bij minder dan [aantal] orders per maand verdien je ons niet terug. Dan zeggen we dat gewoon.</p><p>Maar zit {{bedrijf}} daarboven, dan is het gesprek waarschijnlijk wél de moeite waard. Hoe zit dat bij jullie?</p><p>Met vriendelijke groet,<br>Tom van Biene<br>Viesa Automations<br>www.viesa-automations.nl</p>', 'times'),
  ('email', 'B1 · Drie dingen die ik zag', '3 dingen die ik zag op {{website}}', '<p>Beste {{voornaam}},</p><p>Ik heb een half uur naar {{website}} gekeken. Drie dingen vielen op:</p><ul><li>[Bevinding 1 — concreet, met de pagina erbij]</li><li>[Bevinding 2]</li><li>[Bevinding 3]</li></ul><p>De eerste kost jullie waarschijnlijk het meest, en is het snelst op te lossen.</p><p>Wil je dat ik uitleg hoe? Dan bel ik je een kwartier — verder niets.</p><p>Met vriendelijke groet,<br>Tom van Biene<br>Viesa Automations<br>www.viesa-automations.nl</p>', 'times'),
  ('email', 'B2 · De ongevraagde bevinding', 'Jullie afrekenpagina doet iets geks op mobiel', '<p>Beste {{voornaam}},</p><p>Ik wilde even kijken hoe {{website}} op mobiel bestelt, en liep tegen iets aan: [concreet probleem — bv. de betaalknop valt onder de toetsenbalk op iPhone].</p><p>Ik heb er een schermafbeelding van. Als dit bij meer bezoekers gebeurt, verlies je afrekeningen zonder dat je het in je cijfers terugziet — die mensen komen namelijk nooit tot de bedanktpagina.</p><p>Zal ik ''m sturen? Kost je niets, ook als je verder niets met ons doet.</p><p>Met vriendelijke groet,<br>Tom van Biene<br>Viesa Automations<br>www.viesa-automations.nl</p>', 'times'),
  ('email', 'B3 · De benchmark', '{{bedrijf}} naast negen concurrenten gelegd', '<p>Beste {{voornaam}},</p><p>We hebben voor onszelf in kaart gebracht hoe de webshops in [branche] presteren op laadtijd, mobiele afrekenroute en zoekfunctie. {{bedrijf}} zit daar ook bij.</p><p>Kort samengevat: op [punt] staan jullie duidelijk bovenaan. Op [ander punt] loopt de middenmoot voor.</p><p>Geen namen van anderen natuurlijk, maar de cijfers en jullie eigen positie deel ik graag. Interesse?</p><p>Met vriendelijke groet,<br>Tom van Biene<br>Viesa Automations<br>www.viesa-automations.nl</p>', 'times'),
  ('email', 'B4 · De rekensom', 'Wat zes uur overtypen per week kost', '<p>Beste {{voornaam}},</p><p>Even een rekensom die bij veel bedrijven zoals {{bedrijf}} opgaat.</p><p>Stel: iemand is zes uur per week bezig met orders overzetten tussen systemen. Dat is bijna een volle werkdag, elke week. Op jaarbasis ruim 300 uur — plus de fouten die er onvermijdelijk insluipen.</p><p>Zo''n koppeling bouwen kost eenmalig een fractie daarvan en draait daarna vanzelf.</p><p>Klopt die zes uur ongeveer bij jullie, of zit ik ernaast?</p><p>Met vriendelijke groet,<br>Tom van Biene<br>Viesa Automations<br>www.viesa-automations.nl</p>', 'times'),
  ('email', 'B5 · De weggever', 'Onze checklist: 12 processen die zichzelf kunnen doen', '<p>Beste {{voornaam}},</p><p>We hebben opgeschreven welke twaalf processen we bij webshops en groothandels het vaakst automatiseren — van orderbevestiging tot voorraadsync en incasso-opvolging.</p><p>Per proces staat erbij wat het gemiddeld aan tijd bespaart en hoe ingewikkeld het is om te bouwen. Handig als naslag, ook als je het zelf oppakt.</p><p>Zal ik ''m sturen? Geen formulier, gewoon een reply.</p><p>Met vriendelijke groet,<br>Tom van Biene<br>Viesa Automations<br>www.viesa-automations.nl</p>', 'times'),
  ('email', 'C1 · Nieuwe invalshoek', 'Nog één invalshoek', '<p>Beste {{voornaam}},</p><p>Ik kwam nog iets tegen dat interessanter is dan wat ik je vorige week schreef.</p><p>[Nieuwe invalshoek — een andere kans, een concreet cijfer, iets uit hun branche.]</p><p>Als dit ook niets is, laat het gerust weten. Dan houd ik erover op.</p><p>Met vriendelijke groet,<br>Tom van Biene<br>Viesa Automations<br>www.viesa-automations.nl</p>', 'times'),
  ('email', 'C2 · Het bewijs', 'Hoe [klant] dit oploste', '<p>Beste {{voornaam}},</p><p>Misschien werkt een voorbeeld beter dan mijn uitleg.</p><p>[Klant], vergelijkbaar met {{bedrijf}}, zat met [probleem]. We hebben [ingreep] gebouwd. Sindsdien [resultaat, met een getal].</p><p>Van eerste gesprek tot live: [doorlooptijd].</p><p>Zou datzelfde bij jullie werken, denk je?</p><p>Met vriendelijke groet,<br>Tom van Biene<br>Viesa Automations<br>www.viesa-automations.nl</p>', 'times'),
  ('email', 'C3 · Ben jij de juiste?', 'Ben jij hiervoor de juiste?', '<p>Beste {{voornaam}},</p><p>Ik heb je een paar keer gemaild over het automatiseren van de processen achter jullie webshop, maar krijg geen reactie. Goed mogelijk dat ik gewoon bij de verkeerde persoon aanklop.</p><p>Wie houdt zich bij {{bedrijf}} bezig met de systemen en koppelingen? Als je me de naam geeft, val ik jou verder niet meer lastig.</p><p>Met vriendelijke groet,<br>Tom van Biene<br>Viesa Automations<br>www.viesa-automations.nl</p>', 'times'),
  ('email', 'C4 · De nette afsluiter', 'Ik stop met mailen', '<p>Beste {{voornaam}},</p><p>Dit is mijn laatste bericht — ik blijf niet aan je trekken.</p><p>Mocht het automatiseren van jullie backoffice later toch gaan spelen, dan weet je me te vinden. Ik reageer altijd, ook over een jaar.</p><p>Succes met {{bedrijf}}.</p><p>Met vriendelijke groet,<br>Tom van Biene<br>Viesa Automations<br>www.viesa-automations.nl</p>', 'times'),
  ('email', 'C5 · Een halfjaar later', 'Een halfjaar later', '<p>Beste {{voornaam}},</p><p>We spraken elkaar ongeveer een halfjaar geleden. Toen was het geen goed moment — helder, dat gebeurt.</p><p>Sindsdien is er wel wat veranderd: [wat er veranderde — bij ons, in hun markt, of in de techniek]. Daardoor is [onderwerp] nu een stuk sneller en goedkoper te doen dan toen.</p><p>Is het inmiddels wél een goed moment om er even naar te kijken?</p><p>Met vriendelijke groet,<br>Tom van Biene<br>Viesa Automations<br>www.viesa-automations.nl</p>', 'times'),
  ('email', 'D1 · Afspraak vastgelegd', 'Bevestigd: [datum] om [tijd]', '<p>Beste {{voornaam}},</p><p>Genoteerd: [datum] om [tijd], via [videobellen/telefoon/bij jullie op kantoor]. Reken op drie kwartier.</p><p>Om er meteen wat uit te halen, twee dingen die me helpen:</p><ul><li>Welk proces kost jullie op dit moment de meeste tijd?</li><li>Welke systemen gebruiken jullie nu (webshop, voorraad, boekhouding)?</li></ul><p>Een paar steekwoorden is genoeg — dan kom ik voorbereid.</p><p>Tot [dag]!</p><p>Met vriendelijke groet,<br>Tom van Biene<br>Viesa Automations<br>www.viesa-automations.nl</p>', 'times'),
  ('email', 'D2 · Wat we afspraken', 'Wat we afspraken', '<p>Beste {{voornaam}},</p><p>Bedankt voor het gesprek. Even vastleggen wat we bespraken, dan weten we het allebei nog:</p><ul><li>Grootste knelpunt: [knelpunt]</li><li>Wat het jullie nu kost: [tijd of geld]</li><li>Richting die we voorstelden: [richting]</li></ul><p>Ik pak [onze actie] op en kom uiterlijk [datum] bij je terug. Jij zou [hun actie] nakijken.</p><p>Klopt dit met jouw beeld van het gesprek?</p><p>Met vriendelijke groet,<br>Tom van Biene<br>Viesa Automations<br>www.viesa-automations.nl</p>', 'times'),
  ('email', 'D3 · Het voorstel begeleiden', 'Je voorstel — en waarom deze volgorde', '<p>Beste {{voornaam}},</p><p>Hierbij het voorstel voor {{bedrijf}}. Eén ding vooraf, want dat is belangrijker dan het bedrag onderaan: de volgorde.</p><p>We beginnen bewust met [eerste stap]. Niet omdat dat het grootste is, maar omdat het het snelst iets oplevert — en omdat we daarmee bewijzen dat de rest ook klopt. Pas daarna [tweede stap].</p><p>Zo loop je nooit maanden vooruit te betalen op iets wat je nog niet hebt zien werken.</p><p>Ik hoor graag wat je van die opbouw vindt.</p><p>Met vriendelijke groet,<br>Tom van Biene<br>Viesa Automations<br>www.viesa-automations.nl</p>', 'times'),
  ('email', 'D4 · Wat houdt je tegen?', 'Wat houdt je tegen?', '<p>Beste {{voornaam}},</p><p>Ik ga je niet vragen of je het voorstel al hebt kunnen bekijken — dat helpt ons allebei niet verder.</p><p>Betere vraag: wat is het onderdeel waar je het minst zeker over bent? De prijs, de doorlooptijd, of of het technisch gaat werken met jullie huidige systemen?</p><p>Zeg maar welke van de drie het is, dan pak ik precies dat op.</p><p>Met vriendelijke groet,<br>Tom van Biene<br>Viesa Automations<br>www.viesa-automations.nl</p>', 'times'),
  ('email', 'D5 · De parkeerstand', 'Ik zet ''m op [maand]', '<p>Beste {{voornaam}},</p><p>Helder dat het nu niet uitkomt. Ik zet het bij ons op [maand] en neem dan opnieuw contact op — geen gemail tussendoor.</p><p>Eén ding wil ik nog weten, zodat dat gesprek meteen ergens over gaat: wat moet er tegen die tijd anders zijn wil dit wél kunnen? Budget rond, iemand vrijgemaakt, of eerst [ander project] afronden?</p><p>Met vriendelijke groet,<br>Tom van Biene<br>Viesa Automations<br>www.viesa-automations.nl</p>', 'times'),
  ('email', 'E1 · Naast, niet in plaats van', 'Niet in plaats van jullie bureau', '<p>Beste {{voornaam}},</p><p>Je gaf aan dat jullie al met [partij] werken. Prima — daar willen we ook niet tussen gaan zitten.</p><p>Wat wij doen zit meestal ergens anders: niet de webshop zelf, maar alles erachter. De koppelingen tussen shop, voorraad en boekhouding, en het handwerk dat daar nog omheen zit. De meeste bureaus doen dat niet, en dat is geen kritiek — het is gewoon een ander vak.</p><p>Zullen we een kwartier bellen om te kijken of er overlap is? Zo niet, dan weet je dat ook.</p><p>Met vriendelijke groet,<br>Tom van Biene<br>Viesa Automations<br>www.viesa-automations.nl</p>', 'times'),
  ('email', 'E2 · Kleiner beginnen', 'Kleiner beginnen kan ook', '<p>Beste {{voornaam}},</p><p>Je vond het bedrag te hoog. Terecht om dat te zeggen — en het hoeft ook niet in één keer.</p><p>We kunnen beginnen met alleen [kleinste afgebakende blok], voor [vast bedrag]. Dat staat op zichzelf, levert direct [concreet resultaat] op, en je zit nergens aan vast.</p><p>Bevalt het, dan pakken we de rest. Bevalt het niet, dan heb je in elk geval dat ene stuk werkend.</p><p>Zullen we het zo doen?</p><p>Met vriendelijke groet,<br>Tom van Biene<br>Viesa Automations<br>www.viesa-automations.nl</p>', 'times'),
  ('email', 'E3 · De doorverwijzing', '[verwijzer] zei dat ik je moest mailen', '<p>Beste {{voornaam}},</p><p>[Verwijzer] noemde jouw naam. We hebben voor [hem/haar/hen] [wat we deden] gebouwd, en het gesprek kwam op {{bedrijf}} — volgens [verwijzer] speelt bij jullie iets vergelijkbaars met [onderwerp].</p><p>Klopt dat? Dan bel ik je graag een kwartier. En zo niet, dan hoor ik het net zo graag.</p><p>Met vriendelijke groet,<br>Tom van Biene<br>Viesa Automations<br>www.viesa-automations.nl</p>', 'times'),
  ('belscript', 'A1 · De eerlijke opening', 'Toestemming krijgen om dertig seconden te pitchen', '<p>OPENING — zeg dit rustig, niet gehaast:</p><p>"Goedemiddag {{voornaam}}, je spreekt met Tom van Viesa Automations. Ik val je koud — mag ik dertig seconden om te vertellen waarom ik bel, en dan zeg jij of het zin heeft?"</p><p>WACHT. Laat hem antwoorden. Bijna iedereen zegt ja, omdat je eerlijk was.</p><p>BIJ JA:</p><p>"Wij zorgen dat webshops en groothandels hun bestellingen niet meer met de hand hoeven over te tikken tussen hun shop, voorraad en boekhouding. Meestal loopt daar zes tot tien uur per week in weg.</p><p>Mijn vraag is simpel: gebeurt dat bij {{bedrijf}} ook nog met de hand?"</p><p>WACHT WEER. Dit is de vraag waar het gesprek op draait.</p><p>BIJ NEE OP DE OPENING:</p><p>"Helder. Bel ik beter een andere keer, of is het gewoon niets voor jullie?"</p><p>Dat onderscheid is belangrijk — het eerste is een nieuwe afspraak, het tweede is klaar.</p>', NULL),
  ('belscript', 'A2 · De 30-secondenpitch', 'In één keer duidelijk maken wat we doen en waarom het hen raakt', '<p>Letterlijk uit te spreken. Niet uitbreiden, niet versieren:</p><p>"Wij bouwen de koppelingen tussen de systemen die bedrijven al hebben. Dus je webshop, je voorraadsysteem en je boekhouding gaan met elkaar praten, zodat niemand meer iets hoeft over te tikken.</p><p>Wat dat oplevert is meestal hetzelfde verhaal: een dag per week aan handwerk verdwijnt, en de fouten die daarbij horen ook.</p><p>Wat ik van jou wil weten: hoeveel handwerk zit er nu tussen een binnenkomende bestelling bij {{bedrijf}} en het moment dat die de deur uitgaat?"</p><p>STOP HIER. Je hebt gezegd wat je moest zeggen.</p><p>Let op de drie fouten die je hier makkelijk maakt:<br>• Je noemt techniek (API''s, integraties, middleware). Doe dat niet.<br>• Je noemt jullie eigen verhaal. Interesseert niemand in de eerste minuut.<br>• Je vult de stilte na je vraag. Laat hem denken.</p>', NULL),
  ('belscript', 'A3 · Langs de receptie', 'Bij de juiste persoon terechtkomen zonder te worden afgehouden', '<p>De telefoniste is er om te filteren. Werk mee, niet tegen.</p><p>REGEL 1 — vraag nooit om ''de directeur''. Dat is het signaal dat je verkoopt.<br>REGEL 2 — heb je een naam? Gebruik die alsof je hem kent.</p><p>MET NAAM:</p><p>"Goedemorgen, je spreekt met Tom van Viesa. Is {{voornaam}} er?"</p><p>Kort, rustig, geen uitleg. Uitleg klinkt als verkoop.</p><p>ZONDER NAAM:</p><p>"Goedemorgen, misschien kun je me helpen. Wie houdt zich bij jullie bezig met de systemen achter de webshop — de koppelingen met voorraad en boekhouding?"</p><p>BIJ "waar gaat het over":</p><p>"Over het automatiseren van de orderverwerking. Ik weet niet of het bij jullie speelt — daarom bel ik."</p><p>BIJ "stuur maar een mail":</p><p>"Dat doe ik. Naar wie mag ik het sturen, en wat is zijn of haar e-mailadres?"</p><p>Zo heb je alsnog een naam, en de volgende keer bel je die rechtstreeks.</p>', NULL),
  ('belscript', 'A4 · Voicemail inspreken', 'Teruggebeld worden zonder te verkopen', '<p>Maximaal dertig seconden. Spreek langzaam, vooral je nummer.</p><p>"Hoi {{voornaam}}, Tom van Viesa Automations.</p><p>Ik bel over de orderverwerking bij {{bedrijf}} — ik zag iets op jullie site waar ik nieuwsgierig naar ben, en ik wilde weten of ik het goed zie.</p><p>Bel je me even terug? Nul-zes... [nummer langzaam, twee keer]. Nogmaals: nul-zes... Dank je."</p><p>Waarom dit werkt:<br>• Je noemt geen product. Er valt dus niets af te wijzen.<br>• ''Ik wilde weten of ik het goed zie'' maakt nieuwsgierig.<br>• Je nummer twee keer, langzaam. Anders wordt er niet teruggebeld.</p><p>Spreek maximaal twee keer een voicemail in. Daarna mailen (sjabloon C3).</p>', NULL),
  ('belscript', 'A5 · Nabellen op je mail', 'Van een genegeerde mail alsnog een gesprek maken', '<p>Bel twee tot drie dagen na de mail. Niet eerder.</p><p>"Hoi {{voornaam}}, met Tom van Viesa. Ik heb je dinsdag gemaild over [onderwerp] — waarschijnlijk ondergesneeuwd. Daarom bel ik even."</p><p>Nooit verwijtend, altijd luchtig. Zijn mailbox is niet jouw probleem.</p><p>METEEN DOOR NAAR DE KERN:</p><p>"Het ging hierover: [het concrete punt uit de mail, in één zin].</p><p>Speelt dat bij jullie, of zit ik ernaast?"</p><p>BIJ "ik heb hem niet gelezen":</p><p>"Geeft niet, dan doe ik het nu in dertig seconden." → door naar script A2.</p><p>BIJ "ik heb hem gezien maar het is niets":</p><p>"Dat mag. Mag ik één ding vragen: was het het onderwerp, of gewoon de timing?"</p><p>Dat antwoord bepaalt of je hem later terugbelt of definitief afsluit.</p>', NULL),
  ('belscript', 'A6 · Nabellen op een aanvraag', 'Een warme aanvraag omzetten in een afspraak', '<p>Bel binnen vijf minuten. Echt vijf minuten — dan zit hij nog op de site.</p><p>"Hoi {{voornaam}}, met Tom van Viesa Automations. Je hebt net het formulier ingevuld — ik dacht: ik bel gewoon even, dat gaat sneller dan mailen."</p><p>Dat ''net'' doet het werk. Snelheid is hier je hele voordeel.</p><p>DAN DIRECT:</p><p>"Je schreef [wat hij invulde]. Vertel eens — wat gebeurde er waardoor je dit ging opzoeken?"</p><p>Die vraag is goud. Er is altijd een aanleiding: een fout die geld kostte, iemand die vertrekt, een systeem dat vastloopt. Die aanleiding is je hele verkoopverhaal.</p><p>LUISTEREN. Doorvragen op het moment waarop het misging.</p><p>AFRONDEN:</p><p>"Dit is goed te doen. Ik wil het even goed uitzoeken en je dan laten zien hoe het eruit zou zien. Heb je donderdagochtend een half uur, of komt vrijdagmiddag beter uit?"</p>', NULL),
  ('belscript', 'B1 · Het ontdekkingsgesprek', 'In dertig minuten weten of dit een klant kan worden', '<p>Acht vragen, in deze volgorde. Van breed naar pijnlijk.</p><p>1. "Neem me eens mee: hoe loopt een bestelling bij {{bedrijf}} van binnenkomst tot verzending?"<br>   → Laat hem vertellen. Onderbreek niet. Schrijf mee.</p><p>2. "Waar in dat verhaal moet iemand iets met de hand doen?"<br>   → Hier zitten jullie kansen.</p><p>3. "Hoeveel tijd kost dat per week, denk je?"<br>   → Vraag om een getal. Onthoud het, je hebt het straks nodig.</p><p>4. "En wat gaat er weleens mis?"<br>   → Fouten raken mensen sterker dan tijd. Doorvragen.</p><p>5. "Wat heeft die fout jullie toen gekost?"<br>   → Dit is het moment waarop het concreet wordt. Niet wegpoetsen.</p><p>6. "Hebben jullie eerder geprobeerd dit op te lossen?"<br>   → Zo ja: waarom is het toen niet gelukt? Dat gaat jou ook gebeuren.</p><p>7. "Stel dat het morgen opgelost is — wat verandert er dan bij jullie?"<br>   → Hij verkoopt het nu aan zichzelf. Laat hem praten.</p><p>8. "Wie moet er meekijken als jullie hiermee verder willen?"<br>   → De beslisser, zonder ernaar te vragen.</p><p>AFRONDEN — vat samen in zíjn woorden:</p><p>"Dus als ik het goed samenvat: [knelpunt], het kost jullie [tijd], en het gaat vooral mis bij [moment]. Klopt dat?"</p><p>Dat ''klopt dat'' is belangrijk. Een ja hier is een ja op het probleem — en dat is de helft van de verkoop.</p>', NULL),
  ('belscript', 'B2 · Waar zit het handwerk', 'Het handmatige werk in uren en euro''s krijgen', '<p>Vraag door tot je een getal hebt. Vaag blijven is de valkuil.</p><p>"Wie doet dat overtikken bij jullie?"<br>"Hoeveel bestellingen per dag zijn dat ongeveer?"<br>"En hoe lang doet diegene over één bestelling?"</p><p>REKEN HET HARDOP VOOR — dit is het kantelpunt van het gesprek:</p><p>"Dus als ik het even omreken: [aantal] per dag maal [minuten], dat is ruim [X] uur per week. Op jaarbasis zit je dan tegen de [Y] uur aan. Herken je dat, of valt het in de praktijk mee?"</p><p>WACHT. Vaak komt hier: ''ja, en dan heb ik het nog niet over...'' — precies waar je wilt zijn.</p><p>DOORVRAGEN OP DE FOUTEN:</p><p>"En als er dan een keer iets misgaat in dat overtikken — wat merkt de klant daarvan?"</p><p>Een misgelopen levering of een verkeerde factuur weegt in zijn hoofd zwaarder dan de uren. Gebruik dat later in je voorstel.</p>', NULL),
  ('belscript', 'B3 · Wie beslist er mee', 'De besluitvorming in kaart brengen zonder onbeleefd te zijn', '<p>Vraag nooit ''ben jij degene die beslist''. Dat is beledigend en levert een leugen op.</p><p>VRAAG DIT:</p><p>"Als jullie hiermee verder zouden gaan — hoe gaat dat bij jullie? Wie kijkt er dan mee?"</p><p>Neutraal geformuleerd, en je krijgt het echte antwoord.</p><p>DOORVRAGEN:</p><p>"En wie let er dan vooral op de kosten?"<br>"Is er iemand die het technisch moet goedkeuren?"<br>"Hebben jullie dit soort dingen eerder gedaan? Hoe lang duurde dat toen ongeveer?"</p><p>DE BELANGRIJKSTE VRAAG, aan het eind:</p><p>"En als [naam beslisser] straks vraagt waarom jullie hiervoor kiezen — wat zeg jij dan?"</p><p>Als hij dat niet kan beantwoorden, heb je hem nog niet overtuigd. Dan is het te vroeg voor een voorstel — ga terug naar het probleem.</p>', NULL),
  ('belscript', 'B4 · Budget bespreekbaar maken', 'Weten of er geld is, vóór je een voorstel maakt', '<p>Doe dit in het eerste gesprek. Een voorstel maken voor iemand zonder budget is verspilde tijd.</p><p>LEID IN MET DE KOSTEN VAN NIETS DOEN:</p><p>"We hadden het net over die [X] uur per week. Reken je dat door, dan kost dat jullie ongeveer [bedrag] per jaar — nog los van de fouten."</p><p>DAN DE BANDBREEDTE:</p><p>"Wat wij bouwen zit meestal tussen de [ondergrens] en [bovengrens], eenmalig, afhankelijk van hoeveel systemen er aan moeten hangen.</p><p>Is dat een bedrag waar jullie iets mee kunnen, of zit dat er ver naast?"</p><p>WACHT. Deze stilte voelt ongemakkelijk. Vul hem niet in.</p><p>DRIE MOGELIJKE ANTWOORDEN:</p><ul><li>"Dat kan wel" → door naar de afspraak. Je bent er bijna.</li><li>"Dat is veel" → niet zakken. Vraag: "Wat had je in gedachten?" en kijk of je kleiner kunt beginnen (script C4).</li><li>"Geen idee" → dan praat je met de verkeerde persoon. Terug naar script B3.</li></ul>', NULL),
  ('belscript', 'B5 · Systemen in kaart', 'Weten of we technisch kunnen leveren wat we beloven', '<p>Saai maar noodzakelijk. Zonder dit maak je een voorstel dat je niet kunt waarmaken.</p><p>"Even een paar praktische dingen, dan weet ik of het kan."</p><ul><li>"Op welk platform draait jullie webshop?"</li><li>"Welk boekhoudpakket gebruiken jullie?"</li><li>"Houden jullie voorraad bij in een apart systeem, of in de shop?"</li><li>"Zit er nu al iets tussen die systemen, of gaat alles met de hand?"</li><li>"Wie beheert dat op dit moment — intern of een externe partij?"</li></ul><p>DIE LAATSTE IS DE BELANGRIJKSTE. Zit er een bureau tussen, dan heb je straks hun medewerking nodig. Vraag door:</p><p>"Hoe loopt het met hen? Zouden zij hierin mee willen denken?"</p><p>AFRONDEN:</p><p>"Dit is allemaal goed te koppelen — daar hebben we ervaring mee. Ik ga het even precies uitzoeken en kom bij je terug."</p>', NULL),
  ('belscript', 'C1 · "Geen interesse"', 'Onderscheiden of het een reflex is of een echt nee', '<p>Dit komt bijna altijd in de eerste tien seconden. Het is meestal een reflex, geen oordeel.</p><p>NIET DOEN: doorpraten alsof je het niet hoorde. Dat maakt je een telemarketeer.</p><p>WEL DOEN — erken, dan één vraag:</p><p>"Dat snap ik, je weet nog niet waar ik voor bel. Eén vraag en dan laat ik je met rust:</p><p>worden bestellingen bij {{bedrijf}} nog met de hand overgezet naar de boekhouding?"</p><p>BIJ JA: "Dát is waarvoor ik bel. Mag ik je daar dertig seconden over vertellen?"</p><p>BIJ NEE: "Dan bel ik voor niets, en dan hoor je verder niets van me. Fijne dag."</p><p>En dan ook echt ophangen. Dat is geen verlies — dat is je lijst schoonhouden. Bovendien: iemand die je netjes laat gaan, neemt over een jaar wél op.</p>', NULL),
  ('belscript', 'C2 · "Stuur maar een mailtje"', 'Van een afscheping alsnog een gesprek of een echte afspraak maken', '<p>Het meest voorkomende bezwaar, en zelden een echt verzoek. Meestal betekent het: ik wil dit gesprek beëindigen.</p><p>GA MEE, MAAR STEL ÉÉN VOORWAARDE:</p><p>"Doe ik. Dan wil ik wel weten wat ik erin moet zetten, anders stuur ik je een folder en daar heb je niets aan.</p><p>Twee vragen: gaat het overtikken van bestellingen bij jullie met de hand, en hoeveel tijd kost dat ongeveer?"</p><p>Dat is geen truc — het is waar. En je zit weer in een gesprek.</p><p>GEEFT HIJ ANTWOORD? Dan heb je alsnog je kwalificatie. Rond af met:</p><p>"Helder. Ik stuur je vandaag iets concreets hierover. Mag ik je volgende week even bellen om te horen wat je ervan vond?"</p><p>Vraag om die toestemming. Dan is je volgende belletje afgesproken in plaats van koud.</p><p>HOUDT HIJ VOET BIJ STUK? Stuur de mail, echt waar, en zet een follow-up over vijf dagen.</p>', NULL),
  ('belscript', 'C3 · "Nu even geen tijd"', 'Een concreet nieuw moment vastleggen', '<p>Dit is vaak waar. Behandel het dus niet als bezwaar — behandel het als planning.</p><p>NIET VRAGEN: "wanneer komt het wel uit?" Dat levert ''bel maar eens een keer'' op.</p><p>WEL DOEN — twee opties geven:</p><p>"Geen probleem. Ik bel liever kort dan lang: schikt morgenochtend rond negen uur, of is later in de week beter?"</p><p>Twee opties is makkelijker beantwoorden dan een open vraag.</p><p>BIJ EEN TIJDSTIP: leg het vast in het dashboard als follow-up, en zeg het hardop:</p><p>"Genoteerd, dan bel ik je donderdag om tien uur. Dan houd ik het bij een kwartier."</p><p>BIJ AANHOUDENDE VAAGHEID — één keer testen of het echt aan de tijd ligt:</p><p>"Mag ik eerlijk zijn? Als het gewoon niets voor jullie is, zeg dat dan gerust. Dan bel ik je niet nog eens."</p><p>Dat levert vrijwel altijd het eerlijke antwoord op.</p>', NULL),
  ('belscript', 'C4 · "Te duur"', 'De prijs naast de kosten van niets doen leggen', '<p>Zak nooit direct in prijs. Wie meteen zakt, geeft toe dat de eerste prijs verzonnen was.</p><p>EERST UITZOEKEN WAT HIJ BEDOELT:</p><p>"Dat mag je zeggen. Bedoel je dat het meer is dan je had verwacht, of dat het budget er nu simpelweg niet is?"</p><p>Dat zijn twee heel verschillende gesprekken.</p><p>BIJ ''MEER DAN VERWACHT'' — de rekensom terug:</p><p>"Even naast elkaar: we hadden het over [X] uur per week aan overtikken. Dat is ongeveer [bedrag] per jaar aan loon, en dan reken ik de fouten niet mee.</p><p>Wat wij bouwen is eenmalig [bedrag] en draait daarna vanzelf. Grofweg is dat binnen [periode] terugverdiend. Zie jij dat anders?"</p><p>BIJ ''GEEN BUDGET'' — kleiner maken, niet goedkoper:</p><p>"Dan doen we het anders. We beginnen met alleen [kleinste blok], voor [vast bedrag]. Dat staat op zichzelf en levert meteen [resultaat] op. Werkt dat, dan kijken we verder — en zo niet, dan heb je in elk geval dat stuk werkend."</p><p>Dat is geen korting. Dat is een kleinere eerste stap, en dat is een wezenlijk verschil.</p>', NULL),
  ('belscript', 'C5 · "We hebben al een bureau"', 'Naast de bestaande partij gaan staan in plaats van ertegenin', '<p>Val hun huidige partij nooit af. Dan val je hun eigen keuze af, en dan verlies je.</p><p>BEVESTIG EERST:</p><p>"Goed dat jullie dat geregeld hebben. Wie doet dat voor jullie?"</p><p>Oprecht geïnteresseerd. Je leert er bovendien iets van.</p><p>DAN HET ONDERSCHEID:</p><p>"Wat zij doen — de webshop zelf, de vormgeving, de campagnes — dat doen wij niet. Wij zitten aan de andere kant: alles achter de shop. De koppelingen met voorraad en boekhouding, en het handwerk dat daar nog omheen zit.</p><p>De meeste bureaus doen dat niet. Dat is geen kritiek, het is gewoon een ander vak."</p><p>DAN DE VRAAG DIE ERTOE DOET:</p><p>"Even los van hen: wordt er bij jullie nog met de hand overgetikt tussen de shop en de boekhouding?"</p><p>BIJ JA: dan is dat jouw terrein, en dat van hen niet. Ga verder.<br>BIJ NEE: dan zit het goed, en zeg je dat ook. Vraag of je over een jaar nog eens mag bellen.</p>', NULL),
  ('belscript', 'C6 · "Dat doen we zelf"', 'Het risico van intern bouwen zichtbaar maken', '<p>Meestal is er één handige medewerker die iets in elkaar heeft gezet. Complimenteer dat — het is vaak knap werk.</p><p>"Mooi dat jullie dat intern kunnen. Wie heeft dat gebouwd?"</p><p>LUISTEREN. Dan de vraag die het gesprek opent:</p><p>"En als diegene twee weken op vakantie is en er gaat iets stuk — wie lost het dan op?"</p><p>WACHT. Dit is bijna altijd stil aan de andere kant, want hier heeft niemand een goed antwoord op.</p><p>DOORVRAGEN:</p><p>"Is het gedocumenteerd?"<br>"Hoeveel van zijn tijd gaat er nu op aan onderhoud in plaats van aan zijn eigen werk?"</p><p>POSITIONEREN — niet als vervanger, maar als vangnet:</p><p>"Wij hoeven het niet over te nemen. Waar we vaak binnenkomen is dat we het overnemen wat af is, zodat jullie eigen mensen weer aan hun eigen werk toekomen. En dan ligt het niet meer bij één persoon.</p><p>Zou dat wat zijn?"</p>', NULL),
  ('belscript', 'C7 · "Bel over een halfjaar"', 'Vastleggen wat er dan anders moet zijn', '<p>Ga mee, maar niet zonder inhoud. ''Bel later maar'' zonder afspraak is een beleefd nee.</p><p>AANVAARDEN, DAN DOORVRAGEN:</p><p>"Prima, dan bel ik je in [maand]. Eén ding wil ik dan wel weten, anders bel ik weer voor niets:</p><p>wat moet er tegen die tijd anders zijn wil dit wél kunnen?"</p><p>WACHT OP HET ECHTE ANTWOORD. Er zijn er drie mogelijk:</p><ul><li>"Budget voor volgend jaar" → concreet. Vraag wanneer die begroting rondkomt en bel twee weken daarvóór, niet erna.</li><li>"Eerst [ander project] afronden" → concreet. Vraag wanneer dat klaar is.</li><li>"Gewoon even kijken hoe het loopt" → dat is geen reden. Test het:</li></ul><p>  "Mag ik eerlijk zijn? Dat klinkt alsof het gewoon niet hoog op de lijst staat. Dat mag — dan bel ik je niet meer, en meld je je als het gaat spelen."</p><p>AFRONDEN — leg het hardop vast:</p><p>"Dan noteer ik: bellen in [maand], en dan is [voorwaarde] rond. Tot dan."</p><p>Zet het meteen als follow-up in het dashboard, met die voorwaarde in de notitie.</p>', NULL),
  ('belscript', 'D1 · De afspraak vastzetten', 'Een concreet moment in beide agenda''s krijgen', '<p>Vraag nooit óf hij een afspraak wil. Vraag wanneer.</p><p>SAMENVATTEN, DAN VOORSTELLEN:</p><p>"Dus [knelpunt] kost jullie ongeveer [tijd] per week, en het gaat vooral mis bij [moment].</p><p>Dat is precies wat wij bouwen. Ik wil je laten zien hoe dat er voor {{bedrijf}} uit zou zien — dat is een half uur.</p><p>Schikt donderdagochtend, of is vrijdagmiddag beter?"</p><p>TWEE OPTIES. Niet drie, niet open.</p><p>ZODRA HIJ KIEST — meteen vastleggen, terwijl je aan de lijn bent:</p><p>"Genoteerd. Ik stuur je nu meteen een uitnodiging, dan staat het bij ons allebei. Op welk e-mailadres?"</p><p>Doe dat ook echt tijdens het gesprek. Een afspraak die niet in de agenda staat, bestaat niet.</p><p>AFRONDEN MET DE VOORBEREIDING:</p><p>"Als je vóór donderdag even kunt nakijken hoeveel bestellingen jullie gemiddeld per dag doen, dan kan ik het meteen doorrekenen."</p><p>Een kleine opdracht verhoogt de opkomst aanzienlijk.</p>', NULL),
  ('belscript', 'D2 · Het herinneringsbelletje', 'Voorkomen dat de afspraak niet doorgaat', '<p>De dag ervoor, eind van de ochtend. Kort houden.</p><p>"Hoi {{voornaam}}, Tom van Viesa. We spreken elkaar morgen om [tijd] — ik bel even of dat nog steeds uitkomt."</p><p>Geef hem eerlijk de ruimte om te verzetten. Een verzette afspraak is oneindig veel beter dan een lege agenda.</p><p>GEEF HEM EEN REDEN OM ERNAAR UIT TE KIJKEN:</p><p>"Ik heb inmiddels even naar {{website}} gekeken en twee dingen gevonden die je waarschijnlijk interessant vindt. Neem ik morgen mee."</p><p>AFRONDEN:</p><p>"Tot morgen om [tijd]. Ik bel je op dit nummer."</p><p>MOET HET VERZET? Doe dat direct aan de telefoon, niet per mail:</p><p>"Geen probleem. Volgende week dinsdag zelfde tijd?"</p>', NULL),
  ('belscript', 'D3 · De audit doorbellen', 'Bevindingen toelichten en naar de vervolgstap bewegen', '<p>Mail het verslag nooit zonder het te bespreken. Dan wordt het gescand en vergeten.</p><p>OPENEN MET DE BELANGRIJKSTE BEVINDING, niet met een inleiding:</p><p>"We hebben naar {{bedrijf}} gekeken. Het belangrijkste eerst: [grootste bevinding]. Dat kost jullie naar schatting [impact]."</p><p>STIL ZIJN. Laat hem reageren. Zijn reactie vertelt je of hij het herkent.</p><p>DAN DE REST, KORT:</p><p>"Daarnaast zagen we [tweede] en [derde]. Die zijn kleiner, maar goed mee te nemen."</p><p>TOETSEN:</p><p>"Herken je dit beeld, of zie jij het anders van binnenuit?"</p><p>Neem dat antwoord serieus — hij weet dingen die jij van buitenaf niet kunt zien.</p><p>NAAR DE VERVOLGSTAP:</p><p>"Wat mij betreft pakken we [grootste bevinding] als eerste aan. Ik werk uit wat dat kost en hoe lang het duurt, en stuur je dat deze week.</p><p>Wanneer heb je tijd om het door te nemen?"</p>', NULL),
  ('belscript', 'D4 · Het voorstel nabellen', 'Het echte bezwaar boven tafel krijgen', '<p>Bel twee tot drie dagen na het versturen. En vraag niet of hij het heeft kunnen bekijken — daar krijg je ''nog niet aan toegekomen'' op.</p><p>STEL DEZE VRAAG:</p><p>"Hoi {{voornaam}}, Tom van Viesa. Je hebt het voorstel binnen. Ik ben benieuwd: welk onderdeel sprak je het minst aan?"</p><p>Dat is de hele truc. Je vraagt naar het bezwaar in plaats van naar het oordeel, en dan krijg je een eerlijk antwoord in plaats van beleefdheid.</p><p>DRIE VEELVOORKOMENDE ANTWOORDEN:</p><ul><li>De prijs → script C4.</li><li>De doorlooptijd → "Wat zou wél werken? We kunnen [onderdeel] naar voren halen."</li><li>"Of het technisch gaat werken" → bied een test aan: "Zullen we met één koppeling beginnen en die eerst laten draaien?"</li></ul><p>BIJ ''IK MOET HET NOG INTERN BESPREKEN'':</p><p>"Helder. Met wie bespreek je het, en waar let diegene vooral op?"</p><p>Daarna: "Zal ik daar een korte samenvatting voor maken die je kunt doorsturen?" Dan bepaal jij wat er in die vergadering gezegd wordt.</p>', NULL),
  ('belscript', 'D5 · Akkoord halen', 'Van ''interessant'' naar een handtekening', '<p>Op enig moment moet je het gewoon vragen. De meeste deals stranden omdat niemand de vraag stelt.</p><p>EERST HET LAATSTE BEZWAAR OPZOEKEN:</p><p>"Even eerlijk: is er nog iets waardoor je twijfelt, of zijn we het eens?"</p><p>WACHT. Komt er iets? Los dat eerst op. Komt er niets, dan vraag je het:</p><p>"Dan stel ik voor dat we beginnen. Ik stuur je vanmiddag de opdrachtbevestiging, en dan kunnen we [datum] starten. Akkoord?"</p><p>STIL ZIJN. Wie na de vraag doorpraat, praat de deal weer weg.</p><p>MAAK DE VOLGENDE STAP CONCREET:</p><p>"Dan doe ik dit: bevestiging vanmiddag, jij tekent digitaal, en dan plannen we de startsessie in de week van [datum]. Daar wil ik graag [wie] bij hebben.</p><p>Klopt dat zo?"</p><p>BIJ TWIJFEL — geef hem een uitweg zonder de deal te verliezen:</p><p>"Wil je er nog een nacht over slapen? Dan bel ik je morgen om deze tijd."</p><p>En bel dan ook echt.</p>', NULL),
  ('belscript', 'E1 · Check-in na oplevering', 'Tevredenheid toetsen, en een review of uitbreiding ophalen', '<p>Bel twee weken na livegang. Niet mailen — bellen. Dit gesprek levert reviews, verlengingen en doorverwijzingen op.</p><p>"Hoi {{voornaam}}, Tom van Viesa. [Wat we opleverden] draait nu twee weken. Ik bel niet voor iets — ik wil gewoon weten hoe het bevalt."</p><p>Dat ''ik bel niet voor iets'' ontspant het gesprek meteen.</p><p>DRIE VRAGEN:</p><p>1. "Doet het wat je ervan verwachtte?"<br>2. "Merkt het team het verschil in de praktijk?"<br>3. "Is er iets wat nu irritant of onhandig is?"</p><p>Die derde is de belangrijkste. Er is altijd iets, en als jij er niet naar vraagt hoor je het pas als het te laat is.</p><p>BIJ TEVREDENHEID — vraag om iets terug:</p><p>"Fijn om te horen. Mag ik je iets vragen: zou je daar een paar zinnen over willen zeggen die wij mogen gebruiken? Kost je twee minuten."</p><p>EN DAN DE DOORVERWIJZING:</p><p>"En ken je iemand bij wie ditzelfde speelt? Ik bel liever iemand met jouw naam erbij dan koud."</p>', NULL),
  ('belscript', 'E2 · Factuur nabellen', 'Een concrete betaalafspraak maken zonder de relatie te schaden', '<p>Vriendelijk, feitelijk, en niet verontschuldigend. Je vraagt niet om een gunst — je vraagt om wat is afgesproken.</p><p>OPENEN ZONDER BESCHULDIGING:</p><p>"Hoi {{voornaam}}, Tom van Viesa. Ik bel over factuur [nummer] van [datum] — die staat bij ons nog open. Ik wilde even checken of hij goed is aangekomen."</p><p>Geef hem een eervolle uitweg. Vaak is het gewoon blijven liggen.</p><p>BIJ ''DIE HEB IK NIET GEZIEN'':</p><p>"Kan gebeuren. Ik stuur hem nu opnieuw — naar welk adres het beste?"</p><p>BIJ ''DIE STAAT KLAAR'':</p><p>"Mooi. Wanneer gaat de betaling er ongeveer uit?"</p><p>Vraag om een datum. Zonder datum gebeurt het niet.</p><p>BIJ EEN PROBLEEM — doorvragen, niet aandringen:</p><p>"Is er iets waardoor het niet lukt? Zeg het gerust, dan kijken we of we er samen uitkomen."</p><p>AFRONDEN — altijd met een datum en een bevestiging:</p><p>"Dan noteer ik [datum]. Ik stuur je zo een mailtje met de factuur erbij, dan heb je alles bij elkaar. Bedankt."</p>', NULL),
  ('offerte', 'A1 · Koppeling webshop → boekhouding', NULL, '<p>Beste {{voornaam}},</p><h2>Wat we begrepen hebben</h2><p>Bij {{bedrijf}} worden bestellingen uit de webshop met de hand overgezet naar de boekhouding. Dat kost ongeveer [X] uur per week, en er sluipen fouten in die pas bij de btw-aangifte opvallen.</p><h2>Wat we voorstellen</h2><p>Een koppeling die dat overtikken volledig overneemt:</p><ol><li>Elke betaalde bestelling gaat automatisch als verkoopfactuur naar [boekhoudpakket].</li><li>Btw-tarieven worden per regel meegenomen, ook bij gemengde bestellingen en buitenlandse leveringen.</li><li>Retouren en creditnota''s lopen dezelfde weg terug.</li><li>Mislukt er iets, dan krijg je een melding met de bestelling erbij — geen stille fouten.</li></ol><h2>Wat het oplevert</h2><ul><li>[X] uur per week terug, elke week</li><li>Geen overtypfouten meer in je omzetcijfers</li><li>Altijd actuele cijfers, ook halverwege de maand</li></ul><h2>Investering</h2><p>Alle bedragen zijn exclusief btw. De offerte is dertig dagen geldig.</p><ul><li>Bouw en inrichting koppeling — [bedrag]</li><li>Testen met jullie eigen bestellingen — inbegrepen</li><li>Overdracht en documentatie — inbegrepen</li></ul><h2>Doorlooptijd</h2><p>[X] weken na akkoord, waarvan de laatste week meedraaien naast jullie huidige werkwijze.</p><h2>Wat we van jullie nodig hebben</h2><p>Om de planning te halen hebben we dit van jullie kant nodig:</p><ul><li>Toegang tot de webshop-beheeromgeving</li><li>Een API-sleutel of gebruiker voor [boekhoudpakket]</li><li>Eén contactpersoon die de boekhouding kent</li></ul><p>Met vriendelijke groet,<br>Tom van Biene &amp; Joep Hellemons — Viesa Automations</p>', NULL),
  ('offerte', 'A2 · Voorraadsynchronisatie', NULL, '<p>Beste {{voornaam}},</p><h2>Wat we begrepen hebben</h2><p>De voorraad in de webshop van {{bedrijf}} loopt achter op de werkelijke voorraad. Gevolg: verkopen van producten die er niet zijn, en klanten die achteraf bericht krijgen dat hun bestelling niet doorgaat.</p><h2>Wat we voorstellen</h2><ol><li>Een tweerichtingskoppeling tussen [voorraadsysteem] en de webshop.</li><li>Voorraad wordt elke [interval] bijgewerkt, en direct bij een verkoop.</li><li>Een instelbare buffer per product, zodat hardlopers niet op nul verkopen.</li><li>Een dagelijks overzicht van producten waar het verschil te groot werd.</li></ol><h2>Wat het oplevert</h2><ul><li>Geen nabellen meer over bestellingen die niet geleverd kunnen worden</li><li>Minder handmatige voorraadcorrecties</li><li>Betrouwbare cijfers om op in te kopen</li></ul><h2>Investering</h2><p>Alle bedragen zijn exclusief btw. De offerte is dertig dagen geldig.</p><ul><li>Koppeling en bufferlogica — [bedrag]</li><li>Inregelen per productgroep — [bedrag]</li></ul><h2>Doorlooptijd</h2><p>[X] weken, inclusief een proefperiode op een deel van het assortiment.</p><h2>Wat we van jullie nodig hebben</h2><p>Om de planning te halen hebben we dit van jullie kant nodig:</p><ul><li>Toegang tot [voorraadsysteem]</li><li>Een lijst met producten waarvoor een afwijkende buffer geldt</li></ul><p>Met vriendelijke groet,<br>Tom van Biene &amp; Joep Hellemons — Viesa Automations</p>', NULL),
  ('offerte', 'A3 · Koppeling met de pakketdienst', NULL, '<p>Beste {{voornaam}},</p><h2>Wat we begrepen hebben</h2><p>Verzendlabels worden bij {{bedrijf}} per bestelling met de hand aangemaakt, en track-en-tracecodes worden apart naar de klant gestuurd.</p><h2>Wat we voorstellen</h2><ol><li>Labels worden automatisch aangemaakt zodra een bestelling verzendklaar staat.</li><li>De track-en-tracecode gaat vanzelf terug naar de webshop én naar de klant.</li><li>Verzendmethode wordt gekozen op gewicht, land en gekozen leveroptie.</li><li>Een dagoverzicht van zendingen die vastlopen bij de vervoerder.</li></ol><h2>Wat het oplevert</h2><ul><li>Minder handelingen per bestelling in de piek</li><li>Klanten die zelf hun pakket kunnen volgen, dus minder vragen aan de klantenservice</li><li>Geen verkeerd geadresseerde labels meer</li></ul><h2>Investering</h2><p>Alle bedragen zijn exclusief btw. De offerte is dertig dagen geldig.</p><ul><li>Koppeling met [vervoerder] — [bedrag]</li><li>Extra vervoerder — [bedrag] per stuk</li></ul><h2>Doorlooptijd</h2><p>[X] weken.</p><h2>Wat we van jullie nodig hebben</h2><p>Om de planning te halen hebben we dit van jullie kant nodig:</p><ul><li>Een account bij [vervoerder] met API-toegang</li><li>Jullie verzendtarieven en -regels</li></ul><p>Met vriendelijke groet,<br>Tom van Biene &amp; Joep Hellemons — Viesa Automations</p>', NULL),
  ('offerte', 'A4 · Verkoopkanalen samenbrengen', NULL, '<p>Beste {{voornaam}},</p><h2>Wat we begrepen hebben</h2><p>{{bedrijf}} verkoopt via de eigen webshop én via [kanalen]. Elk kanaal heeft zijn eigen beheeromgeving, en de voorraad wordt op meerdere plekken bijgehouden.</p><h2>Wat we voorstellen</h2><ol><li>Eén centrale plek waar producten en voorraad vandaan komen.</li><li>Bestellingen uit alle kanalen komen op één plek binnen.</li><li>Voorraad wordt over de kanalen verdeeld en bij verkoop overal bijgewerkt.</li><li>Prijzen per kanaal instelbaar, want een marktplaats vraagt om een andere marge.</li></ol><h2>Wat het oplevert</h2><ul><li>Eén keer invoeren in plaats van [aantal] keer</li><li>Geen dubbele verkopen meer van hetzelfde laatste stuk</li><li>Ruimte om een extra kanaal te openen zonder extra werk</li></ul><h2>Investering</h2><p>Alle bedragen zijn exclusief btw. De offerte is dertig dagen geldig.</p><ul><li>Centrale inrichting — [bedrag]</li><li>Per kanaal aansluiten — [bedrag]</li></ul><h2>Doorlooptijd</h2><p>[X] weken, kanaal voor kanaal live.</p><h2>Wat we van jullie nodig hebben</h2><p>Om de planning te halen hebben we dit van jullie kant nodig:</p><ul><li>Toegang tot elk verkoopkanaal</li><li>Afspraken over welke prijs waar geldt</li></ul><p>Met vriendelijke groet,<br>Tom van Biene &amp; Joep Hellemons — Viesa Automations</p>', NULL),
  ('offerte', 'A5 · Maatwerkkoppeling tussen twee systemen', NULL, '<p>Beste {{voornaam}},</p><h2>Wat we begrepen hebben</h2><p>[Systeem A] en [systeem B] praten bij {{bedrijf}} niet met elkaar. De gegevens worden nu overgezet via [export/import of handwerk].</p><h2>Wat we voorstellen</h2><ol><li>In kaart brengen welke gegevens precies heen en weer moeten, en in welke richting.</li><li>Een koppeling die dat op vaste momenten of direct bij een wijziging doet.</li><li>Foutafhandeling met een melding aan een echte persoon — niet alleen een logregel.</li><li>Een testomgeving waarin jullie het kunnen uitproberen voordat het live gaat.</li></ol><h2>Wat het oplevert</h2><ul><li>Geen exportbestanden meer die iemand moet onthouden</li><li>Gegevens die overal hetzelfde zijn</li><li>Een koppeling die van ons is, niet van één medewerker</li></ul><h2>Investering</h2><p>Alle bedragen zijn exclusief btw. De offerte is dertig dagen geldig.</p><ul><li>Analyse en ontwerp — [bedrag]</li><li>Bouw en test — [bedrag]</li></ul><h2>Doorlooptijd</h2><p>[X] weken, waarvan de eerste week analyse.</p><h2>Wat we van jullie nodig hebben</h2><p>Om de planning te halen hebben we dit van jullie kant nodig:</p><ul><li>Documentatie of toegang tot beide systemen</li><li>Iemand die het proces van binnenuit kent</li></ul><p>Met vriendelijke groet,<br>Tom van Biene &amp; Joep Hellemons — Viesa Automations</p>', NULL),
  ('offerte', 'B1 · Webshop sneller maken', NULL, '<p>Beste {{voornaam}},</p><h2>Wat we begrepen hebben</h2><p>{{website}} laadt op mobiel in [X] seconden. Dat kost bezoekers vóórdat ze iets gezien hebben — en het is niet zichtbaar in jullie cijfers, want die mensen komen nooit op een productpagina.</p><h2>Wat we voorstellen</h2><ol><li>Meten waar de tijd blijft: afbeeldingen, scripts van derden, serverantwoord.</li><li>Afbeeldingen omzetten naar moderne formaten en op maat uitleveren.</li><li>Scripts van derden opschonen en uitgesteld laden.</li><li>Caching inrichten voor de pagina''s die het meest bezocht worden.</li></ol><h2>Wat het oplevert</h2><ul><li>Laadtijd naar [doel] seconden op mobiel</li><li>Een meetbaar hogere conversie — vuistregel: elke seconde winst telt</li><li>Betere vindbaarheid, want snelheid weegt mee</li></ul><h2>Investering</h2><p>Alle bedragen zijn exclusief btw. De offerte is dertig dagen geldig.</p><ul><li>Analyse en meting — [bedrag]</li><li>Uitvoering — [bedrag]</li><li>Nameting na twee weken — inbegrepen</li></ul><h2>Doorlooptijd</h2><p>[X] weken.</p><h2>Wat we van jullie nodig hebben</h2><p>Om de planning te halen hebben we dit van jullie kant nodig:</p><ul><li>Toegang tot de hosting en de shop</li><li>Toestemming om scripts van derden te verwijderen</li></ul><p>Met vriendelijke groet,<br>Tom van Biene &amp; Joep Hellemons — Viesa Automations</p>', NULL),
  ('offerte', 'B2 · Afrekenproces verbeteren', NULL, '<p>Beste {{voornaam}},</p><h2>Wat we begrepen hebben</h2><p>Van de bezoekers die bij {{bedrijf}} iets in hun winkelwagen leggen, rondt [percentage] het niet af. Op mobiel ligt dat nog hoger.</p><h2>Wat we voorstellen</h2><ol><li>Het hele afrekenproces stap voor stap doorlopen op telefoon en desktop, en vastleggen waar mensen afhaken.</li><li>Het aantal stappen en verplichte velden terugbrengen tot wat echt nodig is.</li><li>Bezorgkosten en levertijd eerder tonen — de meestgenoemde reden om af te haken.</li><li>Betaalmethoden aanvullen met wat jullie doelgroep verwacht.</li></ol><h2>Wat het oplevert</h2><ul><li>Meer afgeronde bestellingen uit hetzelfde bezoek</li><li>Minder vragen aan de klantenservice over verzendkosten</li><li>Inzicht in wáár het misgaat, ook na deze opdracht</li></ul><h2>Investering</h2><p>Alle bedragen zijn exclusief btw. De offerte is dertig dagen geldig.</p><ul><li>Analyse van het afrekenproces — [bedrag]</li><li>Aanpassingen — [bedrag]</li></ul><h2>Doorlooptijd</h2><p>[X] weken.</p><h2>Wat we van jullie nodig hebben</h2><p>Om de planning te halen hebben we dit van jullie kant nodig:</p><ul><li>Toegang tot de shop en de statistieken</li><li>Inzicht in de huidige betaalmethoden</li></ul><p>Met vriendelijke groet,<br>Tom van Biene &amp; Joep Hellemons — Viesa Automations</p>', NULL),
  ('offerte', 'B3 · Productgegevens op orde', NULL, '<p>Beste {{voornaam}},</p><h2>Wat we begrepen hebben</h2><p>De productgegevens van {{bedrijf}} staan verspreid: deels in de shop, deels in spreadsheets, deels bij de leverancier. Een productwijziging kost daardoor op meerdere plekken werk.</p><h2>Wat we voorstellen</h2><ol><li>Eén plek waar productgegevens vandaan komen, met vaste velden en eenheden.</li><li>Leveranciersbestanden automatisch inlezen en omzetten naar jullie indeling.</li><li>Van daaruit vullen: webshop, verkoopkanalen en documenten.</li><li>Een controle die meldt welke producten nog gegevens missen.</li></ol><h2>Wat het oplevert</h2><ul><li>Eén keer wijzigen in plaats van overal</li><li>Volledige productpagina''s, wat helpt bij vindbaarheid en conversie</li><li>Een nieuw kanaal openen zonder de hele catalogus opnieuw in te voeren</li></ul><h2>Investering</h2><p>Alle bedragen zijn exclusief btw. De offerte is dertig dagen geldig.</p><ul><li>Inrichting centrale productgegevens — [bedrag]</li><li>Per leveranciersbestand — [bedrag]</li></ul><h2>Doorlooptijd</h2><p>[X] weken.</p><h2>Wat we van jullie nodig hebben</h2><p>Om de planning te halen hebben we dit van jullie kant nodig:</p><ul><li>Voorbeeldbestanden van jullie leveranciers</li><li>Een besluit over welke velden verplicht zijn</li></ul><p>Met vriendelijke groet,<br>Tom van Biene &amp; Joep Hellemons — Viesa Automations</p>', NULL),
  ('offerte', 'B4 · Zoekfunctie en filters', NULL, '<p>Beste {{voornaam}},</p><h2>Wat we begrepen hebben</h2><p>Bezoekers die op {{website}} zoeken, vinden niet altijd wat ze zoeken — terwijl juist die bezoekers het vaakst kopen.</p><h2>Wat we voorstellen</h2><ol><li>Een zoekfunctie die typefouten en synoniemen aankan.</li><li>Filters die passen bij hoe jullie klanten denken, niet bij hoe de database is ingedeeld.</li><li>Zoekresultaten met afbeelding, prijs en voorraad in beeld.</li><li>Een overzicht van zoekopdrachten zonder resultaat — dat is je gratis assortimentsonderzoek.</li></ol><h2>Wat het oplevert</h2><ul><li>Hogere conversie bij bezoekers die zoeken</li><li>Zicht op wat klanten zoeken en jullie niet voeren</li><li>Minder afhakers op categoriepagina''s</li></ul><h2>Investering</h2><p>Alle bedragen zijn exclusief btw. De offerte is dertig dagen geldig.</p><ul><li>Inrichting zoekfunctie — [bedrag]</li><li>Filters per categorie — [bedrag]</li></ul><h2>Doorlooptijd</h2><p>[X] weken.</p><h2>Wat we van jullie nodig hebben</h2><p>Om de planning te halen hebben we dit van jullie kant nodig:</p><ul><li>Toegang tot de shop</li><li>Overleg over de filters per productgroep</li></ul><p>Met vriendelijke groet,<br>Tom van Biene &amp; Joep Hellemons — Viesa Automations</p>', NULL),
  ('offerte', 'B5 · Zakelijke bestelomgeving', NULL, '<p>Beste {{voornaam}},</p><h2>Wat we begrepen hebben</h2><p>Zakelijke klanten van {{bedrijf}} bestellen nu per e-mail of telefoon. Elke bestelling wordt bij jullie met de hand ingevoerd, inclusief de afgesproken staffelprijzen.</p><h2>Wat we voorstellen</h2><ol><li>Een afgeschermde omgeving waar zakelijke klanten inloggen en hun eigen prijzen zien.</li><li>Bestellen op artikelnummer en herhaalbestellingen met één klik.</li><li>Bestelgeschiedenis, pakbonnen en facturen zelf te downloaden.</li><li>Bestellingen komen binnen in hetzelfde systeem als de rest.</li></ol><h2>Wat het oplevert</h2><ul><li>Minder invoerwerk bij jullie, meer gemak bij hen</li><li>Geen prijsdiscussies meer — iedereen ziet zijn eigen afspraak</li><li>Klanten die ''s avonds bestellen in plaats van te wachten op kantooruren</li></ul><h2>Investering</h2><p>Alle bedragen zijn exclusief btw. De offerte is dertig dagen geldig.</p><ul><li>Bouw bestelomgeving — [bedrag]</li><li>Inladen klantafspraken — [bedrag]</li></ul><h2>Doorlooptijd</h2><p>[X] weken, met een pilot bij [aantal] klanten.</p><h2>Wat we van jullie nodig hebben</h2><p>Om de planning te halen hebben we dit van jullie kant nodig:</p><ul><li>Overzicht van klantgroepen en prijsafspraken</li><li>Een klant die wil meedenken in de pilot</li></ul><p>Met vriendelijke groet,<br>Tom van Biene &amp; Joep Hellemons — Viesa Automations</p>', NULL),
  ('offerte', 'C1 · Orderverwerking automatiseren', NULL, '<p>Beste {{voornaam}},</p><h2>Wat we begrepen hebben</h2><p>Een bestelling gaat bij {{bedrijf}} door [aantal] handelingen voordat hij de deur uit is. Het meeste daarvan is overtypen en aanvinken.</p><h2>Wat we voorstellen</h2><ol><li>Het proces uittekenen van binnenkomst tot verzending, met de tijd per stap.</li><li>De stappen die geen menselijk oordeel vragen automatiseren.</li><li>De stappen die dát wél doen, voorzien van de informatie om snel te beslissen.</li><li>Een dagstart-overzicht: wat ligt er, wat is blijven hangen, wat is spoed.</li></ol><h2>Wat het oplevert</h2><ul><li>[X] uur per week terug bij de orderverwerking</li><li>Piekdagen zonder overwerk</li><li>Nieuwe medewerkers sneller ingewerkt</li></ul><h2>Investering</h2><p>Alle bedragen zijn exclusief btw. De offerte is dertig dagen geldig.</p><ul><li>Procesanalyse — [bedrag]</li><li>Bouw en inrichting — [bedrag]</li></ul><h2>Doorlooptijd</h2><p>[X] weken, met een meeloopweek aan het eind.</p><h2>Wat we van jullie nodig hebben</h2><p>Om de planning te halen hebben we dit van jullie kant nodig:</p><ul><li>Een dagdeel met de mensen die het werk nu doen</li><li>Toegang tot de betrokken systemen</li></ul><p>Met vriendelijke groet,<br>Tom van Biene &amp; Joep Hellemons — Viesa Automations</p>', NULL),
  ('offerte', 'C2 · Facturatie en aanmaningen', NULL, '<p>Beste {{voornaam}},</p><h2>Wat we begrepen hebben</h2><p>Facturen worden bij {{bedrijf}} met de hand opgemaakt en verstuurd, en het bewaken van openstaande posten gebeurt als iemand eraan denkt.</p><h2>Wat we voorstellen</h2><ol><li>Facturen automatisch opmaken vanuit de geleverde order of het urenoverzicht.</li><li>Versturen per e-mail, met een betaallink erin.</li><li>Een aanmaningsreeks die vanzelf loopt: vriendelijk, dan zakelijk, dan een telefoonsignaal voor jullie.</li><li>Een overzicht van openstaande posten op ouderdom.</li></ol><h2>Wat het oplevert</h2><ul><li>Sneller betaald worden — vaak het grootste effect van deze opdracht</li><li>Geen vergeten facturen meer</li><li>Minder ongemakkelijke belletjes, want de reeks doet het voorwerk</li></ul><h2>Investering</h2><p>Alle bedragen zijn exclusief btw. De offerte is dertig dagen geldig.</p><ul><li>Inrichting facturatie — [bedrag]</li><li>Aanmaningsreeks — [bedrag]</li></ul><h2>Doorlooptijd</h2><p>[X] weken.</p><h2>Wat we van jullie nodig hebben</h2><p>Om de planning te halen hebben we dit van jullie kant nodig:</p><ul><li>Jullie betalingsvoorwaarden</li><li>Toegang tot het boekhoudpakket</li></ul><p>Met vriendelijke groet,<br>Tom van Biene &amp; Joep Hellemons — Viesa Automations</p>', NULL),
  ('offerte', 'C3 · Inkoop en leveranciers', NULL, '<p>Beste {{voornaam}},</p><h2>Wat we begrepen hebben</h2><p>Inkooporders worden bij {{bedrijf}} handmatig opgesteld, en of een levering compleet binnenkwam blijkt vaak pas later.</p><h2>Wat we voorstellen</h2><ol><li>Bestelvoorstellen op basis van voorraad, verkoopsnelheid en levertijd.</li><li>Inkooporders met één handeling versturen naar de leverancier.</li><li>Ontvangst afvinken op de telefoon, met directe verwerking in de voorraad.</li><li>Een signaal bij verschillen tussen besteld, geleverd en gefactureerd.</li></ol><h2>Wat het oplevert</h2><ul><li>Minder nee-verkopen en minder dood kapitaal in het magazijn</li><li>Verschillen die aan het licht komen zolang je er nog iets aan kunt doen</li><li>Inkoop die niet meer op één persoon leunt</li></ul><h2>Investering</h2><p>Alle bedragen zijn exclusief btw. De offerte is dertig dagen geldig.</p><ul><li>Bestelvoorstellen — [bedrag]</li><li>Ontvangst en controle — [bedrag]</li></ul><h2>Doorlooptijd</h2><p>[X] weken.</p><h2>Wat we van jullie nodig hebben</h2><p>Om de planning te halen hebben we dit van jullie kant nodig:</p><ul><li>Levertijden per leverancier</li><li>Toegang tot het voorraadsysteem</li></ul><p>Met vriendelijke groet,<br>Tom van Biene &amp; Joep Hellemons — Viesa Automations</p>', NULL),
  ('offerte', 'C4 · Managementrapportage', NULL, '<p>Beste {{voornaam}},</p><h2>Wat we begrepen hebben</h2><p>De cijfers van {{bedrijf}} staan verspreid over meerdere systemen. Een overzicht maken kost iemand elke maand [X] uur handwerk in Excel.</p><h2>Wat we voorstellen</h2><ol><li>Vaststellen welke cijfers er werkelijk toe doen — liever acht goede dan veertig.</li><li>Die cijfers automatisch ophalen uit de bronsystemen.</li><li>Eén overzicht dat elke ochtend klaarstaat, op telefoon en scherm.</li><li>Een maandrapport dat zichzelf opmaakt en verstuurt.</li></ol><h2>Wat het oplevert</h2><ul><li>[X] uur per maand terug</li><li>Cijfers waar niemand meer over hoeft te discussiëren</li><li>Eerder zien dat iets scheefloopt</li></ul><h2>Investering</h2><p>Alle bedragen zijn exclusief btw. De offerte is dertig dagen geldig.</p><ul><li>Inrichting rapportage — [bedrag]</li><li>Per extra bron — [bedrag]</li></ul><h2>Doorlooptijd</h2><p>[X] weken.</p><h2>Wat we van jullie nodig hebben</h2><p>Om de planning te halen hebben we dit van jullie kant nodig:</p><ul><li>Een sessie om de cijfers vast te stellen</li><li>Toegang tot de bronsystemen</li></ul><p>Met vriendelijke groet,<br>Tom van Biene &amp; Joep Hellemons — Viesa Automations</p>', NULL),
  ('offerte', 'C5 · Documenten en archief', NULL, '<p>Beste {{voornaam}},</p><h2>Wat we begrepen hebben</h2><p>Offertes, opdrachtbevestigingen en pakbonnen worden bij {{bedrijf}} met de hand opgemaakt en op wisselende plekken bewaard.</p><h2>Wat we voorstellen</h2><ol><li>Sjablonen in jullie huisstijl die zich vullen met de juiste gegevens.</li><li>Documenten die vanzelf op de juiste plek in Drive belanden, met een vaste naamgeving.</li><li>Digitaal ondertekenen waar dat mag.</li><li>Terugvinden op klant, datum of bedrag.</li></ol><h2>Wat het oplevert</h2><ul><li>Documenten die er altijd hetzelfde uitzien</li><li>Terugvinden in seconden in plaats van minuten</li><li>Geen versies meer die alleen op iemands bureaublad staan</li></ul><h2>Investering</h2><p>Alle bedragen zijn exclusief btw. De offerte is dertig dagen geldig.</p><ul><li>Sjablonen en opslag — [bedrag]</li><li>Digitaal ondertekenen — [bedrag]</li></ul><h2>Doorlooptijd</h2><p>[X] weken.</p><h2>Wat we van jullie nodig hebben</h2><p>Om de planning te halen hebben we dit van jullie kant nodig:</p><ul><li>Jullie huisstijlbestanden</li><li>Afspraken over de mappenstructuur</li></ul><p>Met vriendelijke groet,<br>Tom van Biene &amp; Joep Hellemons — Viesa Automations</p>', NULL),
  ('offerte', 'D1 · Nieuwe zakelijke website', NULL, '<p>Beste {{voornaam}},</p><h2>Wat we begrepen hebben</h2><p>De website van {{bedrijf}} vertelt niet wat jullie werkelijk doen, en levert nauwelijks aanvragen op.</p><h2>Wat we voorstellen</h2><ol><li>Vaststellen wie er moet landen en welke vraag die persoon heeft.</li><li>Een opbouw die naar één duidelijke actie leidt, per pagina.</li><li>Ontwerp in jullie huisstijl, gebouwd voor telefoon eerst.</li><li>Zelf teksten en afbeeldingen kunnen wijzigen, zonder ons.</li></ol><h2>Wat het oplevert</h2><ul><li>Aanvragen van mensen die al weten waarvoor ze komen</li><li>Een site die je zelf bijhoudt</li><li>Een fundament waar later pagina''s bij kunnen</li></ul><h2>Investering</h2><p>Alle bedragen zijn exclusief btw. De offerte is dertig dagen geldig.</p><ul><li>Ontwerp — [bedrag]</li><li>Bouw — [bedrag]</li><li>Teksten — [bedrag]</li></ul><h2>Doorlooptijd</h2><p>[X] weken, met twee momenten waarop jullie meekijken.</p><h2>Wat we van jullie nodig hebben</h2><p>Om de planning te halen hebben we dit van jullie kant nodig:</p><ul><li>Beeldmateriaal en logo</li><li>Eén beslisser voor de terugkoppeling</li></ul><p>Met vriendelijke groet,<br>Tom van Biene &amp; Joep Hellemons — Viesa Automations</p>', NULL),
  ('offerte', 'D2 · Klantportaal', NULL, '<p>Beste {{voornaam}},</p><h2>Wat we begrepen hebben</h2><p>Klanten van {{bedrijf}} bellen of mailen voor informatie die ze ook zelf zouden kunnen opzoeken: de stand van hun opdracht, hun facturen, hun documenten.</p><h2>Wat we voorstellen</h2><ol><li>Een afgeschermde omgeving waar elke klant zijn eigen dossier ziet.</li><li>Stand van zaken, documenten en facturen op één plek.</li><li>Berichten heen en weer, zodat het niet in mailboxen verdwijnt.</li><li>Een melding bij jullie zodra een klant iets aanlevert.</li></ol><h2>Wat het oplevert</h2><ul><li>Minder vragen die niemand hoeft te beantwoorden</li><li>Klanten die het gevoel hebben dat ze zicht hebben op hun opdracht</li><li>Alles op één plek terug te vinden, ook maanden later</li></ul><h2>Investering</h2><p>Alle bedragen zijn exclusief btw. De offerte is dertig dagen geldig.</p><ul><li>Bouw portaal — [bedrag]</li><li>Koppeling met [systeem] — [bedrag]</li></ul><h2>Doorlooptijd</h2><p>[X] weken, met een pilot bij een paar klanten.</p><h2>Wat we van jullie nodig hebben</h2><p>Om de planning te halen hebben we dit van jullie kant nodig:</p><ul><li>Besluit over wat een klant wel en niet mag zien</li><li>Toegang tot de bronsystemen</li></ul><p>Met vriendelijke groet,<br>Tom van Biene &amp; Joep Hellemons — Viesa Automations</p>', NULL),
  ('offerte', 'D3 · Landingspagina voor een campagne', NULL, '<p>Beste {{voornaam}},</p><h2>Wat we begrepen hebben</h2><p>{{bedrijf}} wil met [campagne] naar buiten. Bezoekers landen nu op de algemene website, waar ze zelf moeten uitzoeken wat de aanbieding was.</p><h2>Wat we voorstellen</h2><ol><li>Eén pagina met één boodschap en één actie.</li><li>Tekst die aansluit op de advertentie waar ze vandaan komen.</li><li>Een formulier dat alleen vraagt wat je echt nodig hebt.</li><li>Meting per bron, zodat je weet welk kanaal werkt.</li></ol><h2>Wat het oplevert</h2><ul><li>Meer aanvragen uit hetzelfde advertentiebudget</li><li>Weten welk kanaal rendeert</li><li>Een opzet die je voor de volgende campagne hergebruikt</li></ul><h2>Investering</h2><p>Alle bedragen zijn exclusief btw. De offerte is dertig dagen geldig.</p><ul><li>Pagina en tekst — [bedrag]</li><li>Meting inrichten — [bedrag]</li></ul><h2>Doorlooptijd</h2><p>[X] weken.</p><h2>Wat we van jullie nodig hebben</h2><p>Om de planning te halen hebben we dit van jullie kant nodig:</p><ul><li>De campagneboodschap</li><li>Toegang tot het advertentieaccount</li></ul><p>Met vriendelijke groet,<br>Tom van Biene &amp; Joep Hellemons — Viesa Automations</p>', NULL),
  ('offerte', 'D4 · Interne werkomgeving', NULL, '<p>Beste {{voornaam}},</p><h2>Wat we begrepen hebben</h2><p>Interne informatie zit bij {{bedrijf}} in mailboxen, mappen en hoofden. Nieuwe medewerkers moeten het vragen, en dat kost twee mensen tijd.</p><h2>Wat we voorstellen</h2><ol><li>Eén plek voor werkafspraken, handleidingen en formulieren.</li><li>Zoeken dat werkt, ook als je niet weet hoe het document heet.</li><li>Aanvragen (verlof, materiaal, declaraties) via een formulier in plaats van een mailtje.</li><li>Beheer bij jullie zelf, zonder dat er iemand voor nodig is die kan programmeren.</li></ol><h2>Wat het oplevert</h2><ul><li>Nieuwe mensen sneller zelfstandig</li><li>Minder onderbrekingen bij de mensen die alles weten</li><li>Afspraken die vindbaar zijn in plaats van mondeling</li></ul><h2>Investering</h2><p>Alle bedragen zijn exclusief btw. De offerte is dertig dagen geldig.</p><ul><li>Inrichting — [bedrag]</li><li>Overzetten bestaande documenten — [bedrag]</li></ul><h2>Doorlooptijd</h2><p>[X] weken.</p><h2>Wat we van jullie nodig hebben</h2><p>Om de planning te halen hebben we dit van jullie kant nodig:</p><ul><li>Een inventarisatie van wat er nu rondzwerft</li><li>Een eigenaar per onderwerp</li></ul><p>Met vriendelijke groet,<br>Tom van Biene &amp; Joep Hellemons — Viesa Automations</p>', NULL),
  ('offerte', 'D5 · Productconfigurator', NULL, '<p>Beste {{voornaam}},</p><h2>Wat we begrepen hebben</h2><p>Producten van {{bedrijf}} worden op maat samengesteld. Elke aanvraag gaat nu heen en weer per e-mail voordat er een prijs op tafel ligt.</p><h2>Wat we voorstellen</h2><ol><li>Een configurator waarin de klant zijn keuzes maakt, met alleen de geldige combinaties.</li><li>Directe prijsberekening volgens jullie regels.</li><li>Een offerte die er meteen uitrolt, in jullie huisstijl.</li><li>De aanvraag komt binnen inclusief alle keuzes — geen navragen meer.</li></ol><h2>Wat het oplevert</h2><ul><li>Van aanvraag naar offerte in minuten in plaats van dagen</li><li>Geen onmogelijke combinaties meer die pas in de productie opvallen</li><li>Aanvragen buiten kantooruren</li></ul><h2>Investering</h2><p>Alle bedragen zijn exclusief btw. De offerte is dertig dagen geldig.</p><ul><li>Configuratielogica — [bedrag]</li><li>Ontwerp en bouw — [bedrag]</li></ul><h2>Doorlooptijd</h2><p>[X] weken, waarvan de eerste aan de regels.</p><h2>Wat we van jullie nodig hebben</h2><p>Om de planning te halen hebben we dit van jullie kant nodig:</p><ul><li>De volledige optielijst met prijsregels</li><li>Iemand die de uitzonderingen kent</li></ul><p>Met vriendelijke groet,<br>Tom van Biene &amp; Joep Hellemons — Viesa Automations</p>', NULL),
  ('offerte', 'E1 · Onderhoudsabonnement', NULL, '<p>Beste {{voornaam}},</p><h2>Wat we begrepen hebben</h2><p>Wat we voor {{bedrijf}} gebouwd hebben moet blijven werken, ook als een leverancier iets wijzigt of er een beveiligingslek opduikt.</p><h2>Wat we voorstellen</h2><ul><li>Bewaking van de koppelingen, met een melding bij ons vóórdat jullie het merken</li><li>Beveiligings- en versie-updates</li><li>Een vast aantal uren per maand voor kleine wijzigingen</li><li>Reactietijd van [X] uur bij een storing</li></ul><h2>Wat het oplevert</h2><ul><li>Geen verrassingen bij een update van een leverancier</li><li>Een vast aanspreekpunt in plaats van zoeken wie er verstand van heeft</li><li>Voorspelbare kosten</li></ul><h2>Investering</h2><p>Alle bedragen zijn exclusief btw. De offerte is dertig dagen geldig.</p><ul><li>Abonnement — [bedrag] per maand</li><li>Meerwerk buiten de uren — [uurtarief]</li></ul><h2>Doorlooptijd</h2><p>Loopt per maand, opzegtermijn één maand.</p><h2>Wat we van jullie nodig hebben</h2><p>Om de planning te halen hebben we dit van jullie kant nodig:</p><ul><li>Een contactpersoon voor storingen</li><li>Toegang tot de omgevingen</li></ul><p>Met vriendelijke groet,<br>Tom van Biene &amp; Joep Hellemons — Viesa Automations</p>', NULL),
  ('offerte', 'E2 · Doorontwikkeling per maand', NULL, '<p>Beste {{voornaam}},</p><h2>Wat we begrepen hebben</h2><p>{{bedrijf}} heeft geen enkel groot project nodig, maar wel een vaste stroom kleine verbeteringen zonder daar telkens een offerte voor te vragen.</p><h2>Wat we voorstellen</h2><ul><li>Een vast aantal uren per maand, in te zetten waar het op dat moment nodig is</li><li>Elke maand samen bepalen wat voorrang krijgt</li><li>Ongebruikte uren schuiven één maand door</li><li>Elke maand een overzicht van wat er gedaan is</li></ul><h2>Wat het oplevert</h2><ul><li>Verbeteren zonder telkens een offertetraject</li><li>Voorspelbare kosten</li><li>Een partij die jullie systemen kent, dus geen inwerktijd</li></ul><h2>Investering</h2><p>Alle bedragen zijn exclusief btw. De offerte is dertig dagen geldig.</p><ul><li>[Aantal] uur per maand — [bedrag]</li><li>Extra uren — [uurtarief]</li></ul><h2>Doorlooptijd</h2><p>Per kwartaal, daarna maandelijks opzegbaar.</p><h2>Wat we van jullie nodig hebben</h2><p>Om de planning te halen hebben we dit van jullie kant nodig:</p><ul><li>Een vast overlegmoment</li><li>Iemand die intern prioriteiten stelt</li></ul><p>Met vriendelijke groet,<br>Tom van Biene &amp; Joep Hellemons — Viesa Automations</p>', NULL),
  ('offerte', 'E3 · Hosting en beheer', NULL, '<p>Beste {{voornaam}},</p><h2>Wat we begrepen hebben</h2><p>De hosting van {{bedrijf}} is verspreid over meerdere partijen, en het is niet altijd duidelijk wie waarvoor verantwoordelijk is als er iets misgaat.</p><h2>Wat we voorstellen</h2><ul><li>Alles onderbrengen op één omgeving, met certificaten en domeinen erbij</li><li>Dagelijkse back-ups, met een terugzetproef die we ook echt uitvoeren</li><li>Bewaking van beschikbaarheid, dag en nacht</li><li>Eén partij die aanspreekbaar is</li></ul><h2>Wat het oplevert</h2><ul><li>Geen verlopen certificaten of domeinen meer</li><li>Back-ups waarvan bewezen is dat ze werken</li><li>Eén nummer om te bellen</li></ul><h2>Investering</h2><p>Alle bedragen zijn exclusief btw. De offerte is dertig dagen geldig.</p><ul><li>Overzetten — eenmalig [bedrag]</li><li>Hosting en beheer — [bedrag] per maand</li></ul><h2>Doorlooptijd</h2><p>Overzetten in [X] weken, buiten kantooruren.</p><h2>Wat we van jullie nodig hebben</h2><p>Om de planning te halen hebben we dit van jullie kant nodig:</p><ul><li>Toegang tot de huidige partijen</li><li>Een gepland moment voor de overgang</li></ul><p>Met vriendelijke groet,<br>Tom van Biene &amp; Joep Hellemons — Viesa Automations</p>', NULL),
  ('offerte', 'E4 · Ondersteuning voor medewerkers', NULL, '<p>Beste {{voornaam}},</p><h2>Wat we begrepen hebben</h2><p>Vragen van medewerkers van {{bedrijf}} over de systemen komen nu bij één collega terecht die er eigenlijk geen tijd voor heeft.</p><h2>Wat we voorstellen</h2><ul><li>Een vast punt waar vragen binnenkomen, per mail of telefoon</li><li>Reactie binnen [X] uur op werkdagen</li><li>Terugkerende vragen omzetten in korte handleidingen</li><li>Een maandoverzicht van wat er speelt — dat wijst de volgende verbetering aan</li></ul><h2>Wat het oplevert</h2><ul><li>Die ene collega kan weer aan zijn eigen werk</li><li>Medewerkers die geholpen worden in plaats van te wachten</li><li>Zicht op waar het systeem nog schuurt</li></ul><h2>Investering</h2><p>Alle bedragen zijn exclusief btw. De offerte is dertig dagen geldig.</p><ul><li>Ondersteuning — [bedrag] per maand</li><li>Buiten kantooruren — [bedrag]</li></ul><h2>Doorlooptijd</h2><p>Per maand, opzegtermijn één maand.</p><h2>Wat we van jullie nodig hebben</h2><p>Om de planning te halen hebben we dit van jullie kant nodig:</p><ul><li>Een lijst met wie waarvoor mag bellen</li><li>Toegang tot de systemen</li></ul><p>Met vriendelijke groet,<br>Tom van Biene &amp; Joep Hellemons — Viesa Automations</p>', NULL),
  ('offerte', 'E5 · Jaarlijkse doorlichting', NULL, '<p>Beste {{voornaam}},</p><h2>Wat we begrepen hebben</h2><p>Wat we voor {{bedrijf}} gebouwd hebben draait, maar het bedrijf verandert. Wat vorig jaar de beste oplossing was, hoeft dat nu niet meer te zijn.</p><h2>Wat we voorstellen</h2><ol><li>Een keer per jaar de hele inrichting doorlopen: koppelingen, processen, techniek.</li><li>Meten wat het inmiddels oplevert en waar nieuwe knelpunten zitten.</li><li>Een verslag met bevindingen, op volgorde van wat het meeste scheelt.</li><li>Een voorstel voor het komende jaar, met bedragen.</li></ol><h2>Wat het oplevert</h2><ul><li>Weten of de investering nog rendeert</li><li>Knelpunten opsporen voordat ze pijn doen</li><li>Een onderbouwd plan in plaats van onderbuikgevoel</li></ul><h2>Investering</h2><p>Alle bedragen zijn exclusief btw. De offerte is dertig dagen geldig.</p><ul><li>Doorlichting en verslag — [bedrag]</li></ul><h2>Doorlooptijd</h2><p>[X] weken, jaarlijks op een vast moment.</p><h2>Wat we van jullie nodig hebben</h2><p>Om de planning te halen hebben we dit van jullie kant nodig:</p><ul><li>Een dagdeel met de betrokken medewerkers</li><li>Toegang tot de cijfers</li></ul><p>Met vriendelijke groet,<br>Tom van Biene &amp; Joep Hellemons — Viesa Automations</p>', NULL),
  ('audit', 'A1 · Webshop-audit (volledig)', NULL, '<h2>Samenvatting</h2><p>We hebben de webshop van {{bedrijf}} doorgelicht op snelheid, mobiel gebruik, het afrekenproces en de productpagina''s. De grootste winst zit in [onderwerp]: dat kost naar schatting [X] omzet per jaar en is binnen [periode] op te lossen.</p><h2>Wat we onderzocht hebben</h2><ul><li>Laadtijd op mobiel en desktop, gemeten op [aantal] pagina''s</li><li>Het volledige afrekenproces, van winkelwagen tot bedankpagina</li><li>Productpagina''s: informatie, beeld, voorraad en verzendinformatie</li><li>Zoekfunctie en filters</li></ul><h2>Bevindingen</h2><p>Op volgorde van wat het meeste kost.</p><ul><li><strong>[Bevinding 1]</strong> — [wat we zagen, met cijfer]. Gevolg: [gevolg].</li><li><strong>[Bevinding 2]</strong> — [wat we zagen]. Gevolg: [gevolg].</li><li><strong>[Bevinding 3]</strong> — [wat we zagen]. Gevolg: [gevolg].</li></ul><h2>Aanbevelingen</h2><ol><li>[Belangrijkste ingreep] — grootste effect, [inspanning]</li><li>[Tweede ingreep] — [inspanning]</li><li>[Derde ingreep] — [inspanning]</li></ol><h2>Verwachte impact</h2><ul><li>Laadtijd van [huidig] naar [doel] seconden</li><li>Geschat [X]% meer afgeronde bestellingen</li><li>Op jaarbasis ongeveer [bedrag]</li></ul><h2>Vervolgstappen</h2><ol><li>Bespreken van dit verslag — een half uur</li><li>Voorstel voor de eerste ingreep</li><li>Nameting [X] weken na oplevering</li></ol>', NULL),
  ('audit', 'A2 · Afrekenproces', NULL, '<h2>Samenvatting</h2><p>Van de bezoekers die bij {{bedrijf}} een product in de winkelwagen leggen, rondt [X]% niet af. Op mobiel is dat [Y]%. De belangrijkste oorzaak is [oorzaak].</p><h2>Wat we onderzocht hebben</h2><ul><li>Het afrekenproces stap voor stap, op telefoon en desktop</li><li>Aantal stappen, velden en verplichte gegevens</li><li>Waar bezorgkosten en levertijd zichtbaar worden</li><li>Beschikbare betaalmethoden</li></ul><h2>Bevindingen</h2><ul><li><strong>Afhaakmoment</strong> — de meeste bezoekers stoppen bij [stap].</li><li><strong>Verzendkosten</strong> — worden pas zichtbaar bij [stap]; dat is de meestgenoemde reden om af te haken.</li><li><strong>Formulier</strong> — [aantal] verplichte velden, waarvan [aantal] niet nodig voor de levering.</li><li><strong>Betaalmethoden</strong> — [wat ontbreekt] wordt door jullie doelgroep verwacht.</li></ul><h2>Aanbevelingen</h2><ol><li>Verzendkosten tonen vanaf de winkelwagen</li><li>Verplichte velden terugbrengen naar [aantal]</li><li>[Betaalmethode] toevoegen</li><li>Afrekenen zonder account mogelijk maken</li></ol><h2>Verwachte impact</h2><ul><li>Afhaakpercentage van [X]% naar [doel]%</li><li>Ongeveer [bedrag] extra omzet per jaar</li></ul><h2>Vervolgstappen</h2><ol><li>Bespreken</li><li>Aanpassingen doorvoeren</li><li>Vier weken meten en vergelijken</li></ol>', NULL),
  ('audit', 'A3 · Mobiel gebruik', NULL, '<h2>Samenvatting</h2><p>[X]% van het bezoek aan {{website}} komt van een telefoon, maar de conversie ligt daar [Y]% lager dan op desktop. Dat verschil is grotendeels op te lossen.</p><h2>Wat we onderzocht hebben</h2><ul><li>De site op [aantal] telefoonformaten, iOS en Android</li><li>Leesbaarheid, knopgroottes en aanraakgebieden</li><li>Menu en navigatie op klein scherm</li><li>Formulieren en toetsenbordgedrag</li></ul><h2>Bevindingen</h2><ul><li><strong>[Bevinding]</strong> — [beschrijving], op [welke toestellen].</li><li><strong>Knoppen</strong> — [aantal] belangrijke knoppen zijn kleiner dan de aanbevolen 44 pixels.</li><li><strong>Tekst</strong> — [waar] is kleiner dan 16 pixels, wat op iOS ongewenst inzoomen veroorzaakt.</li></ul><h2>Aanbevelingen</h2><ol><li>[Belangrijkste mobiele ingreep]</li><li>Knoppen en aanraakgebieden vergroten</li><li>Formulieren het juiste toetsenbord laten openen</li></ol><h2>Verwachte impact</h2><ul><li>Mobiele conversie dichter bij die van desktop</li><li>Ongeveer [bedrag] per jaar</li></ul><h2>Vervolgstappen</h2><ol><li>Bespreken</li><li>Aanpassen</li><li>Nameten op mobiel</li></ol>', NULL),
  ('audit', 'A4 · Productpagina''s', NULL, '<h2>Samenvatting</h2><p>De productpagina''s van {{bedrijf}} missen informatie waar kopers op beslissen. Bij [X] van de [Y] bekeken producten ontbrak [wat].</p><h2>Wat we onderzocht hebben</h2><ul><li>[Aantal] productpagina''s uit [aantal] categorieën</li><li>Beschikbare informatie: maten, materiaal, levertijd, voorraad</li><li>Beeldmateriaal: aantal, kwaliteit, uitsnede</li><li>Beoordelingen en aanvullende producten</li></ul><h2>Bevindingen</h2><ul><li><strong>Ontbrekende gegevens</strong> — [X]% van de producten mist [veld].</li><li><strong>Beeld</strong> — gemiddeld [aantal] foto''s per product; [X] producten hebben er maar één.</li><li><strong>Levertijd</strong> — [wel/niet] zichtbaar vóór het afrekenen.</li><li><strong>Teksten</strong> — [bevinding over overgenomen leveranciersteksten].</li></ul><h2>Aanbevelingen</h2><ol><li>Verplichte velden vaststellen en aanvullen</li><li>Minimaal [aantal] foto''s per product</li><li>Levertijd en voorraad op de productpagina tonen</li><li>Eigen teksten voor de [aantal] bestverkopende producten</li></ol><h2>Verwachte impact</h2><ul><li>Hogere conversie op productpagina''s</li><li>Minder retouren door duidelijkere verwachtingen</li></ul><h2>Vervolgstappen</h2><ol><li>Bespreken</li><li>Velden vaststellen</li><li>Aanvullen, bestsellers eerst</li></ol>', NULL),
  ('audit', 'A5 · Zoeken en navigatie', NULL, '<h2>Samenvatting</h2><p>Bezoekers die zoeken kopen doorgaans het vaakst. Bij {{bedrijf}} levert [X]% van de zoekopdrachten geen enkel resultaat op.</p><h2>Wat we onderzocht hebben</h2><ul><li>De [aantal] meestgebruikte zoekopdrachten</li><li>Omgang met typefouten, meervoud en synoniemen</li><li>Filters per categorie</li><li>Menustructuur en kruimelpad</li></ul><h2>Bevindingen</h2><ul><li><strong>Zonder resultaat</strong> — [X]% van de zoekopdrachten; vaakst [voorbeeld].</li><li><strong>Typefouten</strong> — worden [wel/niet] opgevangen.</li><li><strong>Filters</strong> — [bevinding], bijvoorbeeld [voorbeeld].</li><li><strong>Categorieën</strong> — [aantal] niveaus diep; bezoekers verdwalen bij [waar].</li></ul><h2>Aanbevelingen</h2><ol><li>Zoekfunctie met typefout- en synoniemherkenning</li><li>Synoniemenlijst voor de termen die klanten gebruiken</li><li>Filters per categorie herzien</li><li>Zoekopdrachten zonder resultaat maandelijks bekijken</li></ol><h2>Verwachte impact</h2><ul><li>Hogere conversie bij zoekende bezoekers</li><li>Zicht op gemiste vraag in het assortiment</li></ul><h2>Vervolgstappen</h2><ol><li>Bespreken</li><li>Zoekfunctie inrichten</li><li>Maandelijks de lege zoekopdrachten doornemen</li></ol>', NULL),
  ('audit', 'B1 · Procesaudit backoffice', NULL, '<h2>Samenvatting</h2><p>We hebben de administratieve processen van {{bedrijf}} gevolgd van binnenkomende order tot betaalde factuur. Er gaat naar schatting [X] uur per week op aan werk dat een systeem kan doen.</p><h2>Wat we onderzocht hebben</h2><ul><li>Het orderproces van binnenkomst tot verzending</li><li>Facturatie en debiteurenbewaking</li><li>Inkoop en voorraadbeheer</li><li>Gesprekken met [aantal] medewerkers die het werk dagelijks doen</li></ul><h2>Bevindingen</h2><ul><li><strong>Overtypen</strong> — dezelfde gegevens worden [aantal] keer ingevoerd, in [systemen].</li><li><strong>Handmatige controles</strong> — [X] uur per week aan controlewerk dat geregeld kan worden.</li><li><strong>Eén persoon</strong> — [proces] leunt volledig op één medewerker.</li><li><strong>Fouten</strong> — [aantal] correcties per [periode], vooral bij [waar].</li></ul><h2>Aanbevelingen</h2><ol><li>[Grootste tijdvreter] automatiseren — [X] uur per week</li><li>[Tweede proces] — [X] uur per week</li><li>[Proces] vastleggen zodat het niet van één persoon afhangt</li></ol><h2>Verwachte impact</h2><ul><li>[X] uur per week terug, ongeveer [bedrag] per jaar</li><li>Minder correcties achteraf</li><li>Minder afhankelijk van één medewerker</li></ul><h2>Vervolgstappen</h2><ol><li>Bespreken met het team</li><li>Voorstel voor de eerste twee processen</li><li>Na drie maanden opnieuw meten</li></ol>', NULL),
  ('audit', 'B2 · Doorlooptijd van orders', NULL, '<h2>Samenvatting</h2><p>Een order doet er bij {{bedrijf}} gemiddeld [X] uur over van binnenkomst tot verzending. Daarvan is [Y] uur wachttijd.</p><h2>Wat we onderzocht hebben</h2><ul><li>[Aantal] orders gevolgd van binnenkomst tot verzending</li><li>Tijd per stap, en tijd tussen de stappen</li><li>Wat er gebeurt bij een piek of bij ziekte</li></ul><h2>Bevindingen</h2><ul><li><strong>Wachttijd</strong> — [Y] van de [X] uur is wachten, vooral bij [stap].</li><li><strong>Knelpunt</strong> — [stap] kan maar door [aantal] mensen worden gedaan.</li><li><strong>Piek</strong> — bij meer dan [aantal] orders per dag loopt [stap] vast.</li></ul><h2>Aanbevelingen</h2><ol><li>[Stap] automatisch laten doorlopen in plaats van op iemand wachten</li><li>[Stap] door meer mensen laten uitvoeren</li><li>Signalering op orders die langer dan [X] uur stilstaan</li></ol><h2>Verwachte impact</h2><ul><li>Doorlooptijd van [X] naar [doel] uur</li><li>Piekdagen zonder overwerk</li></ul><h2>Vervolgstappen</h2><ol><li>Bespreken</li><li>Knelpunt aanpakken</li><li>Doorlooptijd blijven meten</li></ol>', NULL),
  ('audit', 'B3 · Debiteuren en betaalgedrag', NULL, '<h2>Samenvatting</h2><p>Klanten van {{bedrijf}} betalen gemiddeld na [X] dagen, bij een betaaltermijn van [Y]. Er staat [bedrag] open, waarvan [bedrag] langer dan 60 dagen.</p><h2>Wat we onderzocht hebben</h2><ul><li>Openstaande posten naar ouderdom</li><li>Betaalgedrag per klantgroep</li><li>Het aanmaanproces zoals het nu loopt</li><li>Betaalmogelijkheden op de factuur</li></ul><h2>Bevindingen</h2><ul><li><strong>Betaaltermijn</strong> — gemiddeld [X] dagen te laat.</li><li><strong>Aanmanen</strong> — gebeurt [hoe], en is daarmee afhankelijk van of iemand eraan denkt.</li><li><strong>Grootste posten</strong> — [aantal] klanten zijn samen goed voor [percentage] van het openstaande bedrag.</li><li><strong>Factuur</strong> — [wel/geen] betaallink.</li></ul><h2>Aanbevelingen</h2><ol><li>Aanmaningsreeks die vanzelf loopt</li><li>Betaallink op elke factuur</li><li>Wekelijks een overzicht op ouderdom</li><li>Afspraken maken met de [aantal] grootste openstaande klanten</li></ol><h2>Verwachte impact</h2><ul><li>Betaaltermijn [X] dagen korter</li><li>Ongeveer [bedrag] eerder beschikbaar</li></ul><h2>Vervolgstappen</h2><ol><li>Bespreken</li><li>Aanmaningsreeks inrichten</li><li>Maandelijks volgen</li></ol>', NULL),
  ('audit', 'B4 · Voorraadbeheer', NULL, '<h2>Samenvatting</h2><p>De voorraadadministratie van {{bedrijf}} wijkt op [X]% van de artikelen af van de werkelijke voorraad. Er ligt voor [bedrag] aan artikelen die het afgelopen jaar niet verkocht zijn.</p><h2>Wat we onderzocht hebben</h2><ul><li>Steekproef op [aantal] artikelen: administratie tegenover werkelijkheid</li><li>Omloopsnelheid per productgroep</li><li>Nee-verkopen in de afgelopen [periode]</li><li>Bestelmomenten en levertijden</li></ul><h2>Bevindingen</h2><ul><li><strong>Afwijkingen</strong> — [X]% van de artikelen klopt niet, gemiddeld [aantal] stuks.</li><li><strong>Stilliggend</strong> — [bedrag] aan artikelen zonder verkoop in twaalf maanden.</li><li><strong>Nee-verkopen</strong> — [aantal] keer, waarvan [aantal] op hardlopers.</li><li><strong>Bestellen</strong> — gebeurt op gevoel in plaats van op verkoopsnelheid.</li></ul><h2>Aanbevelingen</h2><ol><li>Vaste tellingen op de hardlopers</li><li>Bestelvoorstellen op verkoopsnelheid en levertijd</li><li>Actie op de stilliggende voorraad</li><li>Nee-verkopen registreren en maandelijks bekijken</li></ol><h2>Verwachte impact</h2><ul><li>Minder nee-verkopen</li><li>[Bedrag] minder vastgelegd in voorraad</li></ul><h2>Vervolgstappen</h2><ol><li>Bespreken</li><li>Telrondes inrichten</li><li>Bestelvoorstellen invoeren</li></ol>', NULL),
  ('audit', 'B5 · Klantenservice', NULL, '<h2>Samenvatting</h2><p>De klantenservice van {{bedrijf}} behandelt [aantal] vragen per week. Ongeveer [X]% daarvan gaat over iets dat de klant zelf had kunnen opzoeken.</p><h2>Wat we onderzocht hebben</h2><ul><li>[Aantal] vragen uit [periode], ingedeeld naar onderwerp</li><li>Reactietijd en afhandeltijd</li><li>Beschikbare informatie op de website</li></ul><h2>Bevindingen</h2><ul><li><strong>Meestgestelde vraag</strong> — [vraag], [X]% van alle contacten.</li><li><strong>Vermijdbaar</strong> — [X]% gaat over levertijd of bestelstatus.</li><li><strong>Reactietijd</strong> — gemiddeld [X] uur.</li><li><strong>Kanalen</strong> — vragen komen binnen via [aantal] kanalen, zonder één overzicht.</li></ul><h2>Aanbevelingen</h2><ol><li>Bestelstatus zelf op te vragen maken</li><li>Levertijd duidelijker tonen vóór het afrekenen</li><li>Alle kanalen in één overzicht</li><li>Antwoorden op de tien meestgestelde vragen op de site</li></ol><h2>Verwachte impact</h2><ul><li>[X]% minder vragen</li><li>[X] uur per week terug</li><li>Kortere reactietijd</li></ul><h2>Vervolgstappen</h2><ol><li>Bespreken</li><li>Bestelstatus ontsluiten</li><li>Na drie maanden opnieuw indelen</li></ol>', NULL),
  ('audit', 'C1 · Technische doorlichting', NULL, '<h2>Samenvatting</h2><p>De technische inrichting van {{bedrijf}} is doorgelicht op onderhoudbaarheid, beveiliging en continuïteit. Het belangrijkste risico is [risico].</p><h2>Wat we onderzocht hebben</h2><ul><li>Versies van de gebruikte software en hun ondersteuning</li><li>Hosting, certificaten en domeinen</li><li>Back-ups en of ze terug te zetten zijn</li><li>Toegangsrechten en beheeraccounts</li></ul><h2>Bevindingen</h2><ul><li><strong>Verouderd</strong> — [component] draait op [versie]; ondersteuning is geëindigd op [datum].</li><li><strong>Back-ups</strong> — [bevinding]; een terugzetproef is [wel/niet] ooit gedaan.</li><li><strong>Toegang</strong> — [aantal] accounts met volledige rechten, waarvan [aantal] van oud-medewerkers.</li><li><strong>Certificaten</strong> — [bevinding over verlooptermijnen].</li></ul><h2>Aanbevelingen</h2><ol><li>[Component] bijwerken — dit is het grootste risico</li><li>Terugzetproef uitvoeren en jaarlijks herhalen</li><li>Ongebruikte beheeraccounts intrekken</li><li>Bewaking op verlopende certificaten en domeinen</li></ol><h2>Verwachte impact</h2><ul><li>Kleiner risico op uitval</li><li>Aantoonbaar werkende back-ups</li></ul><h2>Vervolgstappen</h2><ol><li>Bespreken</li><li>Bijwerken plannen buiten kantooruren</li><li>Jaarlijks herhalen</li></ol>', NULL),
  ('audit', 'C2 · Datakwaliteit', NULL, '<h2>Samenvatting</h2><p>De klant- en productgegevens van {{bedrijf}} bevatten dubbelingen en lege velden. Van de [aantal] klantrecords is [X]% vermoedelijk dubbel.</p><h2>Wat we onderzocht hebben</h2><ul><li>[Aantal] klantrecords op dubbelingen en volledigheid</li><li>[Aantal] producten op ontbrekende velden</li><li>Schrijfwijzen en eenheden</li><li>Hoe gegevens binnenkomen</li></ul><h2>Bevindingen</h2><ul><li><strong>Dubbelingen</strong> — [aantal] vermoedelijk dubbele klanten.</li><li><strong>Leeg</strong> — [X]% mist [veld], waardoor [gevolg].</li><li><strong>Schrijfwijzen</strong> — [voorbeeld] komt in [aantal] varianten voor.</li><li><strong>Oorzaak</strong> — bij binnenkomst wordt niets gecontroleerd.</li></ul><h2>Aanbevelingen</h2><ol><li>Bestaande dubbelingen opruimen</li><li>Controle bij invoer, zodat het niet terugkomt</li><li>Vaste schrijfwijzen en eenheden vastleggen</li><li>Maandelijkse controle op nieuwe afwijkingen</li></ol><h2>Verwachte impact</h2><ul><li>Betrouwbare cijfers</li><li>Minder misgelopen leveringen</li><li>Bruikbare klantsegmenten</li></ul><h2>Vervolgstappen</h2><ol><li>Bespreken</li><li>Opschonen</li><li>Invoercontrole inbouwen</li></ol>', NULL),
  ('audit', 'C3 · Koppelingen doorlichten', NULL, '<h2>Samenvatting</h2><p>{{bedrijf}} gebruikt [aantal] koppelingen tussen systemen. [Aantal] daarvan zijn kwetsbaar, en bij [aantal] merkt niemand het als ze stilvallen.</p><h2>Wat we onderzocht hebben</h2><ul><li>Alle koppelingen in kaart: wat gaat waarheen, hoe vaak</li><li>Foutafhandeling en meldingen</li><li>Wie het beheert en wie het begrijpt</li><li>Wat er gebeurt als een koppeling uitvalt</li></ul><h2>Bevindingen</h2><ul><li><strong>Stille fouten</strong> — bij [aantal] koppelingen komt een fout nergens terecht.</li><li><strong>Kennis</strong> — [aantal] koppelingen zijn alleen bekend bij [persoon].</li><li><strong>Handwerk</strong> — [koppeling] moet met de hand worden gestart.</li><li><strong>Geen documentatie</strong> — voor [aantal] koppelingen.</li></ul><h2>Aanbevelingen</h2><ol><li>Meldingen bij fouten, naar een persoon en niet naar een logbestand</li><li>Documenteren wat er waarheen gaat</li><li>[Koppeling] automatisch laten lopen</li><li>Bewaking op koppelingen die stilvallen</li></ol><h2>Verwachte impact</h2><ul><li>Fouten binnen een dag zichtbaar</li><li>Minder afhankelijk van één persoon</li></ul><h2>Vervolgstappen</h2><ol><li>Bespreken</li><li>Meldingen inrichten</li><li>Documentatie aanvullen</li></ol>', NULL),
  ('audit', 'C4 · Meting en statistieken', NULL, '<h2>Samenvatting</h2><p>De cijfers waarop {{bedrijf}} stuurt kloppen niet volledig. Het verschil tussen de gemeten en de werkelijke omzet is [X]%.</p><h2>Wat we onderzocht hebben</h2><ul><li>Inrichting van de statistieken</li><li>Gemeten omzet tegenover de werkelijke omzet</li><li>Doelen en trechters</li><li>Toestemmingsbanner en de invloed daarvan op de meting</li></ul><h2>Bevindingen</h2><ul><li><strong>Verschil</strong> — [X]% tussen gemeten en werkelijke omzet.</li><li><strong>Dubbel geteld</strong> — [bevinding].</li><li><strong>Doelen</strong> — [aantal] ingericht, waarvan [aantal] verkeerd.</li><li><strong>Toestemming</strong> — [X]% weigert, en dat verkeer valt volledig weg uit de cijfers.</li></ul><h2>Aanbevelingen</h2><ol><li>Meting opnieuw inrichten en controleren tegen de werkelijke omzet</li><li>Dubbeltellingen wegnemen</li><li>Doelen opnieuw vaststellen</li><li>Maandelijkse controle op het verschil</li></ol><h2>Verwachte impact</h2><ul><li>Cijfers waarop je kunt sturen</li><li>Weten welk kanaal echt rendeert</li></ul><h2>Vervolgstappen</h2><ol><li>Bespreken</li><li>Meting herstellen</li><li>Maandelijks controleren</li></ol>', NULL),
  ('audit', 'C5 · Hosting en beschikbaarheid', NULL, '<h2>Samenvatting</h2><p>De website van {{bedrijf}} was in de afgelopen [periode] [X] keer onbereikbaar, in totaal [tijd]. De hosting is niet ingericht op jullie piekmomenten.</p><h2>Wat we onderzocht hebben</h2><ul><li>Beschikbaarheid over [periode]</li><li>Serverantwoordtijden onder normale en piekbelasting</li><li>Verdeling van diensten over leveranciers</li><li>Herstelprocedure bij uitval</li></ul><h2>Bevindingen</h2><ul><li><strong>Uitval</strong> — [X] keer, samen [tijd]; steeds bij [oorzaak].</li><li><strong>Piek</strong> — antwoordtijd loopt op van [X] naar [Y] ms.</li><li><strong>Versnippering</strong> — [aantal] leveranciers, geen duidelijke verantwoordelijkheid.</li><li><strong>Herstel</strong> — geen vastgelegde procedure.</li></ul><h2>Aanbevelingen</h2><ol><li>[Oorzaak van de uitval] wegnemen</li><li>Capaciteit afstemmen op de piek</li><li>Diensten onderbrengen bij één partij</li><li>Herstelprocedure vastleggen en beproeven</li></ol><h2>Verwachte impact</h2><ul><li>[Bedrag] minder omzetverlies door uitval</li><li>Snellere site tijdens de piek</li></ul><h2>Vervolgstappen</h2><ol><li>Bespreken</li><li>Oorzaak aanpakken</li><li>Beschikbaarheid blijven meten</li></ol>', NULL),
  ('audit', 'D1 · Vindbaarheid in zoekmachines', NULL, '<h2>Samenvatting</h2><p>{{website}} wordt gevonden op [aantal] zoektermen. Op de [aantal] termen die er commercieel toe doen staat de site gemiddeld op plek [X].</p><h2>Wat we onderzocht hebben</h2><ul><li>Posities op de belangrijkste zoektermen</li><li>Technische vindbaarheid: indexering, snelheid, structuur</li><li>Inhoud tegenover die van [aantal] concurrenten</li><li>Verwijzingen van andere sites</li></ul><h2>Bevindingen</h2><ul><li><strong>Gemiste termen</strong> — [aantal] termen met samen [aantal] zoekopdrachten per maand waarop jullie niet voorkomen.</li><li><strong>Technisch</strong> — [bevinding], bijvoorbeeld [voorbeeld].</li><li><strong>Inhoud</strong> — concurrenten hebben [aantal] pagina''s over [onderwerp], jullie [aantal].</li><li><strong>Verwijzingen</strong> — [aantal] verwijzende domeinen tegenover gemiddeld [aantal] bij concurrenten.</li></ul><h2>Aanbevelingen</h2><ol><li>[Technische ingreep] — voorwaarde voor de rest</li><li>Pagina''s maken voor de [aantal] belangrijkste gemiste termen</li><li>Bestaande pagina''s uitbreiden op [onderwerp]</li><li>Verwijzingen opbouwen via [aanpak]</li></ol><h2>Verwachte impact</h2><ul><li>[Aantal] extra bezoekers per maand</li><li>Ongeveer [bedrag] aan bespaarde advertentiekosten</li></ul><h2>Vervolgstappen</h2><ol><li>Bespreken</li><li>Technische ingrepen eerst</li><li>Elk kwartaal posities meten</li></ol>', NULL),
  ('audit', 'D2 · Advertentiebudget', NULL, '<h2>Samenvatting</h2><p>{{bedrijf}} besteedt [bedrag] per maand aan advertenties. Daarvan gaat naar schatting [X]% naar vertoningen die niets opleveren.</p><h2>Wat we onderzocht hebben</h2><ul><li>Campagnestructuur en budgetverdeling</li><li>Zoektermen waarop daadwerkelijk is vertoond</li><li>Landingspagina''s per campagne</li><li>Meting van conversies</li></ul><h2>Bevindingen</h2><ul><li><strong>Verspilling</strong> — [bedrag] per maand naar zoektermen zonder enige conversie.</li><li><strong>Landingspagina''s</strong> — [aantal] campagnes wijzen naar de algemene homepage.</li><li><strong>Meting</strong> — conversies worden [wel/niet] betrouwbaar teruggemeld.</li><li><strong>Uitsluitingen</strong> — [aantal] uitsluitingstermen ingesteld; dat is te weinig.</li></ul><h2>Aanbevelingen</h2><ol><li>Niet-converterende zoektermen uitsluiten</li><li>Landingspagina per campagne</li><li>Conversiemeting herstellen</li><li>Budget verschuiven naar wat aantoonbaar rendeert</li></ol><h2>Verwachte impact</h2><ul><li>[Bedrag] per maand minder verspilling</li><li>Lagere kosten per aanvraag</li></ul><h2>Vervolgstappen</h2><ol><li>Bespreken</li><li>Uitsluitingen doorvoeren</li><li>Na een maand opnieuw beoordelen</li></ol>', NULL),
  ('audit', 'D3 · E-mailmarketing', NULL, '<h2>Samenvatting</h2><p>Het bestand van {{bedrijf}} telt [aantal] adressen. De openingsgraad is [X]% en er wordt [frequentie] verstuurd — er blijft omzet liggen.</p><h2>Wat we onderzocht hebben</h2><ul><li>Omvang en kwaliteit van het bestand</li><li>Openings- en klikcijfers over [periode]</li><li>Automatische reeksen: welkom, verlaten winkelwagen, na aankoop</li><li>Bezorgbaarheid en technische instellingen</li></ul><h2>Bevindingen</h2><ul><li><strong>Reeksen</strong> — [aantal] van de gebruikelijke reeksen ontbreekt, waaronder [welke].</li><li><strong>Bezorgbaarheid</strong> — [bevinding over SPF, DKIM en DMARC].</li><li><strong>Bestand</strong> — [X]% is al [periode] niet actief geweest.</li><li><strong>Segmentatie</strong> — iedereen krijgt dezelfde mail.</li></ul><h2>Aanbevelingen</h2><ol><li>Reeks voor verlaten winkelwagens — meestal de snelste winst</li><li>Welkomstreeks voor nieuwe inschrijvingen</li><li>Technische instellingen op orde brengen</li><li>Inactieve adressen opschonen of heractiveren</li></ol><h2>Verwachte impact</h2><ul><li>Ongeveer [bedrag] extra omzet per jaar</li><li>Betere bezorging in de inbox</li></ul><h2>Vervolgstappen</h2><ol><li>Bespreken</li><li>Reeks voor verlaten winkelwagens</li><li>Maandelijks volgen</li></ol>', NULL),
  ('audit', 'D4 · Inhoud en teksten', NULL, '<h2>Samenvatting</h2><p>De teksten op {{website}} beschrijven wat {{bedrijf}} doet, maar niet welk probleem het voor de lezer oplost. Dat is de belangrijkste reden dat bezoekers niet doorklikken.</p><h2>Wat we onderzocht hebben</h2><ul><li>De [aantal] belangrijkste pagina''s</li><li>Opbouw, koppen en aanzet tot actie</li><li>Leesbaarheid en jargon</li><li>Vergelijking met [aantal] concurrenten</li></ul><h2>Bevindingen</h2><ul><li><strong>Perspectief</strong> — [X] van de [Y] pagina''s begint over jullie in plaats van over de lezer.</li><li><strong>Actie</strong> — [aantal] pagina''s hebben geen duidelijke vervolgstap.</li><li><strong>Jargon</strong> — [voorbeelden] worden niet uitgelegd.</li><li><strong>Bewijs</strong> — geen cijfers, cases of klantverhalen.</li></ul><h2>Aanbevelingen</h2><ol><li>Openingsalinea''s herschrijven vanuit de lezer</li><li>Eén duidelijke vervolgstap per pagina</li><li>[Aantal] klantverhalen met concrete cijfers</li><li>Jargon vervangen of uitleggen</li></ol><h2>Verwachte impact</h2><ul><li>Meer aanvragen uit hetzelfde bezoek</li><li>Betere aansluiting bij de doelgroep</li></ul><h2>Vervolgstappen</h2><ol><li>Bespreken</li><li>Belangrijkste pagina''s herschrijven</li><li>Meten wat het doet</li></ol>', NULL),
  ('audit', 'D5 · Vergelijking met concurrenten', NULL, '<h2>Samenvatting</h2><p>We hebben {{bedrijf}} naast [aantal] concurrenten gelegd. Jullie staan sterk op [sterkte]; op [zwakte] loopt de markt voor.</p><h2>Wat we onderzocht hebben</h2><ul><li>[Aantal] concurrenten in [branche]</li><li>Assortiment, prijsstelling en levervoorwaarden</li><li>Snelheid, mobiel gebruik en afrekenproces</li><li>Vindbaarheid en advertentie-inzet</li></ul><h2>Bevindingen</h2><ul><li><strong>Sterk</strong> — op [punt] presteren jullie beter dan alle vergeleken partijen.</li><li><strong>Achterstand</strong> — op [punt] scoort de middenmoot beter.</li><li><strong>Voorwaarden</strong> — [aantal] concurrenten bieden [voorwaarde] die jullie niet bieden.</li><li><strong>Onderscheid</strong> — [bevinding over hoe jullie je positioneren].</li></ul><h2>Aanbevelingen</h2><ol><li>[Achterstand] wegwerken — dit kost nu klanten</li><li>[Sterkte] veel nadrukkelijker uitdragen</li><li>[Voorwaarde] overwegen</li></ol><h2>Verwachte impact</h2><ul><li>Betere positie op [punt]</li><li>Duidelijker onderscheid in de markt</li></ul><h2>Vervolgstappen</h2><ol><li>Bespreken</li><li>Achterstand aanpakken</li><li>Jaarlijks opnieuw vergelijken</li></ol>', NULL),
  ('audit', 'E1 · AVG en privacy', NULL, '<h2>Samenvatting</h2><p>De verwerking van persoonsgegevens bij {{bedrijf}} is doorgelicht. Er zijn [aantal] punten die aandacht vragen, waarvan [aantal] met een reëel boeterisico.</p><h2>Wat we onderzocht hebben</h2><ul><li>Welke persoonsgegevens worden vastgelegd en waarom</li><li>Bewaartermijnen en opschoning</li><li>Verwerkersovereenkomsten met leveranciers</li><li>Toestemmingsbanner en verwerking van verzoeken</li></ul><h2>Bevindingen</h2><ul><li><strong>Bewaartermijnen</strong> — [bevinding]; gegevens uit [jaar] staan er nog.</li><li><strong>Verwerkersovereenkomsten</strong> — ontbreken bij [aantal] leveranciers.</li><li><strong>Toestemming</strong> — de banner [voldoet wel/niet]; [toelichting].</li><li><strong>Verzoeken</strong> — geen vastgelegde werkwijze voor inzage of verwijdering.</li></ul><h2>Aanbevelingen</h2><ol><li>Verwerkersovereenkomsten afsluiten met [leveranciers]</li><li>Bewaartermijnen vastleggen en automatisch opschonen</li><li>Toestemmingsbanner aanpassen</li><li>Werkwijze vastleggen voor verzoeken van betrokkenen</li></ol><h2>Verwachte impact</h2><ul><li>Kleiner boeterisico</li><li>Aantoonbaar in orde bij een controle</li></ul><h2>Vervolgstappen</h2><ol><li>Bespreken</li><li>Overeenkomsten regelen</li><li>Jaarlijks opnieuw doorlopen</li></ol>', NULL),
  ('audit', 'E2 · Informatiebeveiliging', NULL, '<h2>Samenvatting</h2><p>De beveiliging van de systemen van {{bedrijf}} is beoordeeld. Het grootste risico is [risico]; dat is binnen [periode] op te lossen.</p><h2>Wat we onderzocht hebben</h2><ul><li>Toegangsrechten en beheeraccounts</li><li>Wachtwoordbeleid en tweestapsverificatie</li><li>Bijgewerkte versies en bekende kwetsbaarheden</li><li>Beveiliging van back-ups</li></ul><h2>Bevindingen</h2><ul><li><strong>[Grootste risico]</strong> — [beschrijving en gevolg].</li><li><strong>Tweestapsverificatie</strong> — staat aan bij [aantal] van de [aantal] accounts.</li><li><strong>Oud-medewerkers</strong> — [aantal] accounts nog actief.</li><li><strong>Versies</strong> — [aantal] onderdelen met een bekende kwetsbaarheid.</li></ul><h2>Aanbevelingen</h2><ol><li>[Grootste risico] wegnemen — met voorrang</li><li>Tweestapsverificatie verplichten</li><li>Accounts van oud-medewerkers intrekken</li><li>Vast moment voor het bijwerken van versies</li></ol><h2>Verwachte impact</h2><ul><li>Aanzienlijk kleiner risico op een incident</li><li>Aantoonbaar beleid richting klanten</li></ul><h2>Vervolgstappen</h2><ol><li>Bespreken</li><li>Grootste risico aanpakken</li><li>Halfjaarlijks herhalen</li></ol>', NULL),
  ('audit', 'E3 · Continuïteit', NULL, '<h2>Samenvatting</h2><p>We hebben gekeken wat er bij {{bedrijf}} gebeurt als een systeem, leverancier of medewerker wegvalt. Op [aantal] plekken is er geen terugvaloptie.</p><h2>Wat we onderzocht hebben</h2><ul><li>Afhankelijkheid van afzonderlijke systemen en leveranciers</li><li>Kennis die bij één persoon zit</li><li>Back-ups en herstelprocedures</li><li>Wat er gebeurt bij langdurige uitval</li></ul><h2>Bevindingen</h2><ul><li><strong>Eén persoon</strong> — [proces] kan alleen door [rol] worden uitgevoerd.</li><li><strong>Eén leverancier</strong> — [dienst] heeft geen alternatief.</li><li><strong>Herstel</strong> — geschatte hersteltijd na uitval: [tijd].</li><li><strong>Beproefd</strong> — herstel is [wel/niet] ooit geoefend.</li></ul><h2>Aanbevelingen</h2><ol><li>[Proces] vastleggen en een tweede persoon inwerken</li><li>Herstelprocedure opstellen en beproeven</li><li>Alternatief onderzoeken voor [dienst]</li><li>Jaarlijks een herstelproef</li></ol><h2>Verwachte impact</h2><ul><li>Hersteltijd van [X] naar [doel]</li><li>Minder afhankelijk van personen</li></ul><h2>Vervolgstappen</h2><ol><li>Bespreken</li><li>Vastleggen en inwerken</li><li>Herstelproef plannen</li></ol>', NULL),
  ('audit', 'E4 · Leveranciers en contracten', NULL, '<h2>Samenvatting</h2><p>{{bedrijf}} heeft [aantal] doorlopende contracten voor software en diensten, samen [bedrag] per jaar. Daarvan wordt [aantal] nauwelijks of niet gebruikt.</p><h2>Wat we onderzocht hebben</h2><ul><li>Alle doorlopende contracten en abonnementen</li><li>Werkelijk gebruik tegenover afgenomen licenties</li><li>Opzegtermijnen en verlengingsdata</li><li>Overlap tussen diensten</li></ul><h2>Bevindingen</h2><ul><li><strong>Ongebruikt</strong> — [bedrag] per jaar aan diensten die niemand gebruikt.</li><li><strong>Overlap</strong> — [dienst A] en [dienst B] doen grotendeels hetzelfde.</li><li><strong>Licenties</strong> — [aantal] afgenomen, [aantal] in gebruik.</li><li><strong>Verlenging</strong> — [aantal] contracten verlengen stilzwijgend.</li></ul><h2>Aanbevelingen</h2><ol><li>[Bedrag] aan ongebruikte diensten opzeggen</li><li>Kiezen tussen [dienst A] en [dienst B]</li><li>Licenties terugbrengen naar het werkelijke aantal</li><li>Verlengingsdata in de agenda zetten</li></ol><h2>Verwachte impact</h2><ul><li>[Bedrag] per jaar besparing</li><li>Overzicht over wat er loopt</li></ul><h2>Vervolgstappen</h2><ol><li>Bespreken</li><li>Opzeggingen vóór de verlengingsdata</li><li>Jaarlijks doorlopen</li></ol>', NULL),
  ('audit', 'E5 · Nulmeting vóór een traject', NULL, '<h2>Samenvatting</h2><p>Vóór de start van [traject] is de huidige situatie bij {{bedrijf}} vastgelegd. Dit verslag is het ijkpunt waartegen we het resultaat straks afmeten.</p><h2>Wat we vastgelegd hebben</h2><ul><li>Tijdsbesteding per proces, gemeten over [periode]</li><li>Aantallen: orders, facturen, contactmomenten</li><li>Foutpercentages en correcties</li><li>Kosten van de huidige werkwijze</li></ul><h2>Uitgangssituatie</h2><ul><li><strong>Tijd</strong> — [X] uur per week aan [proces].</li><li><strong>Volume</strong> — [aantal] per [periode].</li><li><strong>Fouten</strong> — [X]%, ongeveer [aantal] correcties per [periode].</li><li><strong>Kosten</strong> — ongeveer [bedrag] per jaar.</li></ul><h2>Wat we gaan meten</h2><ol><li>Dezelfde cijfers, [periode] na oplevering</li><li>Tussenmeting halverwege</li><li>Ervaring van de betrokken medewerkers</li></ol><h2>Verwachte impact</h2><ul><li>Doel: [X] uur per week terug</li><li>Doel: foutpercentage naar [doel]%</li></ul><h2>Vervolgstappen</h2><ol><li>Verslag vaststellen</li><li>Traject starten</li><li>Nameting op [datum]</li></ol>', NULL),
  ('audit', 'Leeg auditverslag', NULL, '<h2>Samenvatting</h2>
<p>Korte samenvatting van de bevindingen voor {{bedrijf}}.</p>
<h2>Huidige situatie</h2>
<ul><li>…</li></ul>
<h2>Knelpunten &amp; kansen</h2>
<ul><li>…</li></ul>
<h2>Aanbevelingen</h2>
<ol><li>…</li></ol>
<h2>Verwachte impact</h2>
<ul><li>Tijdsbesparing: …</li><li>Kosten: …</li></ul>', NULL),
  ('offerte', 'Lege offerte', NULL, '<p>Beste {{voornaam}},</p>
<p>Naar aanleiding van ons contact ontvang je hierbij onze offerte voor {{bedrijf}}.</p>
<h2>Voorgestelde werkzaamheden</h2>
<ul><li>Onderdeel — prijsindicatie</li></ul>
<h2>Investering</h2>
<p>Totaal: —</p>
<p>Met vriendelijke groet,<br>Tom &amp; Joep — Viesa Automations</p>', NULL)
) as v(type, naam, onderwerp, inhoud_html, lettertype)
where not exists (
  select 1 from public.sjablonen s
  where s.type = v.type and s.naam = v.naam
);

-- Controle: wat staat er nu?
select type, count(*) as aantal
from public.sjablonen
group by type
order by type;
